    .skill-level-control {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 12px 16px;
      background: #f8f9fa;
      border-radius: 12px;
    }

    .skill-level-control.locked {
      justify-content: center;
      color: #b2bec3;
      gap: 8px;
    }

    .skill-level-control.special {
      justify-content: center;
    }

    .skill-level-control.special.learned {
      color: #27ae60;
      gap: 6px;
    }

    .level-display {
      display: flex;
      flex-direction: column;
      gap: 2px;
    }

    .level-label {
      font-size: 0.7rem;
      color: #999;
    }

    .level-value {
      font-size: 1.1rem;
      font-weight: 700;
      color: #2d3436;
      font-family: var(--font-tech);
    }

    .level-buttons {
      display: flex;
      gap: 6px;
    }

    .level-btn {
      width: 36px;
      height: 36px;
      border: 1px solid #e0e0e0;
      background: #fff;
      border-radius: 8px;
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1rem;
      color: #636e72;
    }

    .level-btn:hover:not(.disabled) {
      background: #f0f0f0;
      border-color: #ccc;
    }

    .level-btn.disabled {
      opacity: 0.35;
      cursor: not-allowed;
    }

    .level-btn.level-up {
      background: linear-gradient(135deg, #00b894 0%, #00cec9 100%);
      border-color: transparent;
      color: #fff;
    }

    .level-btn.level-down {
      background: #fff0f0;
      border-color: #ffcccc;
      color: #e74c3c;
    }

    .level-btn.level-min,
    .level-btn.level-max {
      width: 32px;
      font-size: 0.85rem;
    }

    .level-cap-hint {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 6px;
      padding: 8px 12px;
      background: #fff8e6;
      border-radius: 8px;
      color: #e67e22;
      font-size: 0.75rem;
      margin-top: -4px;
    }

    .skill-equip-btn {
      width: 100%;
      padding: 12px;
      border: none;
      border-radius: 10px;
      cursor: pointer;
      font-size: 0.85rem;
      font-weight: 600;
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 6px;
    }

    .skill-equip-btn.equip {
      background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
      color: #fff;
    }

    .skill-equip-btn.equip:hover {
      opacity: 0.9;
    }

    .skill-equip-btn.unequip {
      background: #f5f5f5;
      color: #666;
      border: 1px solid #e0e0e0;
    }

    .skill-equip-btn.unequip:hover {
      background: #ffebee;
      border-color: #e57373;
      color: #e74c3c;
    }

    .skill-learn-special {
      padding: 10px 28px;
      border: none;
      background: linear-gradient(135deg, #00b894 0%, #00cec9 100%);
      color: #fff;
      border-radius: 8px;
      cursor: pointer;
      font-size: 0.85rem;
      font-weight: 600;
