        font-size: 0.95rem;
        border-radius: 8px;
      }

      /* 导航栏行不加额外padding，保持原样 */

      /* 盾牌：窄屏下用 CSS order 移到 char-header 第一行右上角 */
      .char-header {
        display: grid;
        grid-template-columns: auto 1fr auto;
        grid-template-rows: auto auto;
        gap: 6px 10px;
        align-items: center;
      }

      .avatar {
        grid-row: 1;
        grid-column: 1;
        width: 56px;
        height: 56px;
      }

      .char-details {
        grid-row: 1;
        grid-column: 2;
        min-width: 0;
      }

      /* 盾牌放到头像/名字那一行的右侧 */
      .armor-block {
        grid-row: 1;
        grid-column: 3;
        margin: 0;
      }

      /* HP/CP 条占第二行全宽 */
      .hp-container {
        grid-row: 2;
        grid-column: 1 / -1;
        max-width: none;
        min-width: 0;
      }

      .bar-value {
        font-size: 0.55rem;
      }

      .buff-bar {
        gap: 6px;
      }

      .buff-icon-item {
        width: 32px;
        height: 32px;
        border-radius: 6px;
