        if (type === '庄园' || type === '领地' || type === '房产') return 'type-estate';
        return 'type-default';
      }
      function cleanBusinessText(raw) {
        return String(raw === undefined || raw === null ? '' : raw)
          .replace(/\r?\n/g, ' ')
          .replace(/^[\s;；,，。]+|[\s;；,，。]+$/g, '')
          .trim();
      }
      function isEmptyBusinessValue(raw) {
        var text = cleanBusinessText(raw);
        if (!text) return true;
        var normalized = text.toLowerCase()
          .replace(/\s+/g, '')
          .replace(/[;；,，。!！?？、:：]/g, '');
        var emptyWords = new Set([
          '无', '暂无', '空', '无产出', '暂无产出', '无固定产出', '无收益', '暂无收益',
          'none', 'null', 'nil', 'n/a', 'na', '-', '--', '/'
        ]);
        return emptyWords.has(normalized);
      }
      function parseLegacyBusinessEffect(raw) {
        var text = cleanBusinessText(raw);
        if (!text) return null;
        var funcMatch = text.match(/功能\s*[：:]\s*([\s\S]*?)(?=(?:[；;。]\s*周(?:产|产出|收益|收入)\s*[：:])|$)/);
        var outputMatch = text.match(/周(?:产|产出|收益|收入)\s*[：:]\s*([\s\S]*?)(?=(?:[；;。]\s*功能\s*[：:])|$)/);
        if (!funcMatch || !outputMatch) return null;
        var func = cleanBusinessText(funcMatch[1]);
        var output = cleanBusinessText(outputMatch[1]);
        if (!func || !output) return null;
        return { func: func, output: output };
      }
      function normalizeBusinessEffect(seq) {
        seq = seq || {};
        var func = cleanBusinessText(seq.功能);
        var output = cleanBusinessText(seq.产出);
