            const messageData = mvuState.mvu.getMvuData({ type: 'message', message_id: 'latest' });
            const chatData = mvuState.mvu.getMvuData({ type: 'chat' });
            const messageStatData = messageData?.stat_data || {};
            const chatStatData = chatData?.stat_data || {};
            if (Object.keys(messageStatData).length > 0) {
              // Dynamic character data must come from latest message so removed keys stay removed.
              // Only stable system configuration falls back to chat when latest is partial.
              finalData = {
                ...messageStatData,
                系统配置: {
                  ...(chatStatData?.系统配置 || {}),
                  ...(messageStatData?.系统配置 || {})
                }
              };
