        const messageText = String(msg || '确认执行该操作吗？');
        const highlightText = String(opts.highlightText || '');
        const highlightIndex = highlightText ? messageText.indexOf(highlightText) : -1;
        if (highlightIndex >= 0) {
          message.appendChild(document.createTextNode(messageText.slice(0, highlightIndex)));
          const highlight = document.createElement('span');
          highlight.className = 'danger-text';
          highlight.textContent = highlightText;
          message.appendChild(highlight);
          message.appendChild(document.createTextNode(messageText.slice(highlightIndex + highlightText.length)));
        } else {
          message.textContent = messageText;
        }

        const actions = document.createElement('div');
        actions.className = 'battle-confirm-actions';

        const cancelBtn = document.createElement('button');
        cancelBtn.type = 'button';
        cancelBtn.className = 'battle-confirm-btn cancel';
        cancelBtn.textContent = opts.cancelText || '取消';

        const okBtn = document.createElement('button');
        okBtn.type = 'button';
        okBtn.className = 'battle-confirm-btn ok';
        if (opts.variant === 'neutral') okBtn.classList.add('is-neutral');
