            if (patch.op === 'replace' || patch.op === 'add') {
              let obj = mvuData.stat_data;
              for (let i = 0; i < parts.length - 1; i++) { if (!obj[parts[i]]) obj[parts[i]] = {}; obj = obj[parts[i]]; }
              obj[parts[parts.length - 1]] = patch.value;
            } else if (patch.op === 'remove') {
              let obj = mvuData.stat_data;
              for (let i = 0; i < parts.length - 1; i++) { if (!obj[parts[i]]) return; obj = obj[parts[i]]; }
              delete obj[parts[parts.length - 1]];
            }
          });
          await mvuState.mvu.replaceMvuData(mvuData, { type: 'message', message_id: 'latest' });
          return true;
        } catch (e) {
          console.warn('[status-bar] MVU write failed:', e);
          return false;
        }
      };
      const BOND_BRIEF_PATH_PREFIX = '/羁绊列表/';
      const normalizeBriefDisplayPath = (path) => typeof path === 'string' ? path.trim() : '';
      const getBriefDisplayPathList = (data) => {
        const paths = data?.系统配置?.简详显示?.简要显示路径;
        return Array.isArray(paths) ? paths.map(normalizeBriefDisplayPath).filter(Boolean) : [];
      };
      const buildBondBriefDisplayPath = (bondName) => `${BOND_BRIEF_PATH_PREFIX}${bondName}`;
      const isBondDetailVisible = (data, bondName) => !getBriefDisplayPathList(data).includes(buildBondBriefDisplayPath(bondName));
      const DEFAULT_SKILL_SYSTEM_MODE = 'classic';
