      const normalizeSkillSystemMode = (mode) => mode === 'combo' ? 'combo' : DEFAULT_SKILL_SYSTEM_MODE;
      const getSkillSystemMode = (data) => normalizeSkillSystemMode(data?.系统配置?.技能系统模式);
