        const normalized = String(mode || '').trim().toLowerCase();
        return (normalized === 'new' || normalized === '新版') ? 'new' : DEFAULT_COMBAT_VALUE_MODE;
      };
      const getCombatValueMode = (data) => normalizeCombatValueMode(data?.系统配置?.战斗数值模式);
      const getSkillSlotConfig = (data) => {
        const mode = getSkillSystemMode(typeof data === 'string' ? null : data);
        const raceName = typeof data === 'string' ? data : (data?.人物?.种族 || data?.种族 || '');
        const isElf = raceName === '森精种';
        return {
          mode,
          isElf,
          main: mode === 'combo' ? 9 : (isElf ? 8 : 7),
          awakening: isElf ? 3 : 2
        };
      };
      const COMBO_RELEVANT_TIERS = ['基础', '转职', '进阶', '必杀', '奥义'];
      const COMBO_ADVANCED_GROUP_ORDER = ['alpha', 'beta', 'gamma'];
      const COMBO_GROUP_ORDER = [...COMBO_ADVANCED_GROUP_ORDER, 'ultimate'];
