          觉醒一: { 习得等级: 50, 等级上限: 3, SP消耗: 0, 冷却: 3, 升级所需等级基数: 12, 升级所需等级成长: 3, 伤害: { 基础: 3150, 成长: 350 } },
          觉醒二: { 习得等级: 85, 等级上限: 2, SP消耗: 0, 冷却: 4, 升级所需等级基数: 15, 升级所需等级成长: 0, 伤害: { 基础: 4200, 成长: 700 } },
          觉醒三: { 习得等级: 100, 等级上限: 1, SP消耗: 0, 冷却: 5, 升级所需等级基数: 99, 升级所需等级成长: 0, 伤害: { 基础: 5600, 成长: 0 } }
        },
        new: {
          基础: { 习得等级: 1, 等级上限: 15, SP消耗: 10, 冷却: 1, 升级所需等级基数: 1, 升级所需等级成长: 0, 伤害: { 基础: 130, 成长: 5 } },
          转职: { 习得等级: 10, 等级上限: 15, SP消耗: 20, 冷却: 1, 升级所需等级基数: 1, 升级所需等级成长: 0, 伤害: { 基础: 150, 成长: 5 } },
          进阶: { 习得等级: 20, 等级上限: 10, SP消耗: 30, 冷却: 1, 升级所需等级基数: 2, 升级所需等级成长: 0, 伤害: { 基础: 200, 成长: 10 } },
          必杀: { 习得等级: 30, 等级上限: 7, SP消耗: 50, 冷却: 2, 升级所需等级基数: 4, 升级所需等级成长: 1, 伤害: { 基础: 300, 成长: 20 } },
          奥义: { 习得等级: 40, 等级上限: 5, SP消耗: 80, 冷却: 3, 升级所需等级基数: 4, 升级所需等级成长: 1, 伤害: { 基础: 400, 成长: 25 } },
          觉醒一: { 习得等级: 50, 等级上限: 3, SP消耗: 0, 冷却: 3, 升级所需等级基数: 12, 升级所需等级成长: 3, 伤害: { 基础: 500, 成长: 50 } },
          觉醒二: { 习得等级: 85, 等级上限: 2, SP消耗: 0, 冷却: 4, 升级所需等级基数: 15, 升级所需等级成长: 0, 伤害: { 基础: 650, 成长: 50 } },
          觉醒三: { 习得等级: 100, 等级上限: 1, SP消耗: 0, 冷却: 5, 升级所需等级基数: 99, 升级所需等级成长: 0, 伤害: { 基础: 800, 成长: 0 } }
        }
      };
      const TIER_CONFIG = SKILL_TIER_CONFIG_BY_MODE.classic;
      const getSkillTierConfig = (data) => SKILL_TIER_CONFIG_BY_MODE[getCombatValueMode(data)] || SKILL_TIER_CONFIG_BY_MODE.classic;
      const SUMMON_DAMAGE_RATIO_BY_TIER = {
        基础: 1.0,
        转职: 1.0,
        进阶: 0.8,
        必杀: 0.65,
        奥义: 0.5
      };
      const getSummonDamageRatioByTier = (tierName = '', data = null) => {
        if (getCombatValueMode(data) === 'new') return 0.6;
        return SUMMON_DAMAGE_RATIO_BY_TIER[tierName] ?? 0.5;
      };
      const getSkillBaseDamage = (skill, data = null) => {
        const tier = getSkillTierConfig(data)[skill.阶位];
        if (!tier) return 0;
        if (skill.类型 === '特殊' || skill.类型 === '职业特殊') return 0;
        const level = skill.当前等级 || 0;
        if (level === 0) return 0;
        const activeBase = tier.伤害.基础 + tier.伤害.成长 * (level - 1);
        if (skill.类型 !== '召唤') return activeBase;
        const ratio = getSummonDamageRatioByTier(skill.阶位, data);
        return Math.round(activeBase * ratio);
      };
      const calcSkillDamage = (skill, data = null) => {
        const base = getSkillBaseDamage(skill, data);
        if (base <= 0) return 0;
        // 向下浮动 0~10%，凑整到10的倍数
        const floatRatio = 1 - Math.random() * 0.10;
        return Math.round(base * floatRatio / 10) * 10;
      };
      const getSpecialEffect = (skill) => {
        if (!skill.特殊效果 || (skill.当前等级 || 0) === 0) return null;
        // 职业特殊技能：特殊效果是字符串，直接返回
        if (typeof skill.特殊效果 === 'string') return skill.特殊效果;
        // 普通特殊技能：特殊效果是对象，按等级获取
        const currentLv = skill.当前等级 || 1;
        // 先尝试精确匹配
        if (skill.特殊效果[String(currentLv)]) {
          return skill.特殊效果[String(currentLv)];
        }
        // 找不到精确匹配时，找不超过当前等级的最大等级
        const validKeys = Object.keys(skill.特殊效果)
          .map(k => parseInt(k))
          .filter(k => !isNaN(k) && k <= currentLv)
          .sort((a, b) => b - a);
        if (validKeys.length > 0) {
          return skill.特殊效果[String(validKeys[0])];
