       */
      const getSpecialEffectObj = (skill) => {
        const lv = String(skill.当前等级 || 1);
        if (!skill.特殊效果 || (skill.当前等级 || 0) === 0) return { [lv]: '无' };
        if (typeof skill.特殊效果 === 'string') return skill.特殊效果;
        if (skill.特殊效果[lv]) {
          return { [lv]: skill.特殊效果[lv] };
        }
        const validKeys = Object.keys(skill.特殊效果)
          .map(k => parseInt(k))
          .filter(k => !isNaN(k) && k <= parseInt(lv))
          .sort((a, b) => b - a);
        if (validKeys.length > 0) {
          const key = String(validKeys[0]);
          return { [key]: skill.特殊效果[key] };
        }
        return { [lv]: '无' };
      };
      const parseSlotMeta = (raw) => {
        if (!raw) return null;
        try { return JSON.parse(decodeURIComponent(raw)); } catch (e) { }
        try { return JSON.parse(raw); } catch (e) { return null; }
      };
      const encodeSlotMeta = (meta) => {
        try { return encodeURIComponent(JSON.stringify(meta)); } catch (e) { return ''; }
      };
      const buildEquippedSkillSlotData = (data, skillName) => {
        const skillTree = data?.人物?.技能树 || {};
        const skillList = skillTree.技能列表 || {};
        const skill = skillList[skillName] || {};
        if (!skillName || !skill || (skill.当前等级 || 0) <= 0) return null;
        const mainSkillSlots = data?.人物?.主动技能槽 || {};
        const existingSlotData = mainSkillSlots[skillName];
        if (existingSlotData) return existingSlotData;
        const skillForCalc = Object.assign({}, skill, { 当前等级: skill.当前等级 || 1 });
        return {
          名称: skillName,
          类型: skill.类型 || '主动',
          技能等级: skill.当前等级 || 1,
          冷却中: false,
          伤害倍率: calcSkillDamage(skillForCalc, data),
          阶位: skill.阶位 || '基础',
          特殊效果: getSpecialEffectObj(skillForCalc),
          描述: skill.描述 || ''
        };
      };
      const buildComboActiveSlotData = (data, skillName, skill = null) => {
        const skillTree = data?.人物?.技能树 || {};
        const skillList = skillTree.技能列表 || {};
        const fullSkill = skill || skillList[skillName] || {};
        if (!skillName || !fullSkill || (fullSkill.当前等级 || 0) <= 0) return null;
        const currentMainSlots = data?.人物?.主动技能槽 || {};
        const existingSlotData = currentMainSlots[skillName];
        const slotData = existingSlotData ? { ...existingSlotData } : (buildEquippedSkillSlotData(data, skillName) || {});
        if (!slotData) return null;
        slotData.名称 = skillName;
        slotData.类型 = fullSkill.类型 || slotData.类型 || '主动';
        slotData.技能等级 = fullSkill.当前等级 || slotData.技能等级 || 1;
        slotData.冷却中 = slotData.冷却中 === true || (fullSkill.冷却计数 || 0) > 0;
        if (!slotData.伤害倍率) {
          slotData.伤害倍率 = calcSkillDamage({ ...fullSkill, 当前等级: fullSkill.当前等级 || 1 }, data);
        }
        slotData.阶位 = fullSkill.阶位 || slotData.阶位 || '基础';
        slotData.特殊效果 = getSpecialEffectObj({ ...fullSkill, 当前等级: fullSkill.当前等级 || 1 });
        slotData.描述 = fullSkill.描述 || slotData.描述 || '';
        if (fullSkill.召唤物名称) slotData.召唤物名称 = fullSkill.召唤物名称;
        else if (slotData.召唤物名称) delete slotData.召唤物名称;
        return slotData;
      };
      const buildComboActiveMainSlots = (data, comboState = null) => {
