        var i = 0;

        for (i = 0; i < baseSlots.length; i++) {
          if (baseSlots[i]) result.push(baseSlots[i]);
        }
        for (i = 0; i < classSlots.length; i++) {
          if (classSlots[i]) result.push(classSlots[i]);
        }
        for (i = 0; i < advancedSlots.length; i++) {
          if (advancedSlots[i]) result.push(advancedSlots[i]);
        }
        return result;
      }

      function getComboSlotArrayRef(comboState, slotMeta) {
        if (!comboState || !slotMeta || !slotMeta.comboSlot) return null;
