        patches.push({ op: 'add', path: '/系统配置/组合技能状态/转职技能槽', value: nextState.转职技能槽 });
        patches.push({ op: 'add', path: '/系统配置/组合技能状态/高级技能组配置', value: nextState.高级技能组配置 });
        patches.push({ op: 'add', path: '/人物/主动技能槽', value: nextActiveSlots });
        currentActiveNames.forEach(function (skillName) {
          if (nextActiveNames.includes(skillName)) return;
          patches.push({ op: 'replace', path: `/人物/技能树/技能列表/${skillName}/是否装备`, value: false });
