        var nextState = getComboEquipState(data);
        var slotArray = getComboSlotArrayRef(nextState, slotMeta);
        if (!slotArray) return false;
        slotArray[slotMeta.slotIndex] = skillName || '';
        return saveComboConfigState(data, nextState);
