      function openComboGroupConfigurator(focusGroupKey) {
        document.getElementById('combo-config-overlay')?.remove();
        const d = fetchLatestMvuData();
        const comboState = getComboEquipState(d);
        const skillList = d?.人物?.技能树?.技能列表 || {};
        const activeDisplayGroup = getComboDisplayGroupKey(comboState);
        const groupDescriptions = {
          alpha: '由槽位 1 + 槽位 2 触发时显示本组高级技能',
          beta: '由槽位 3 + 槽位 4 触发时显示本组高级技能',
          gamma: '由槽位 5 + 槽位 6 触发时显示本组高级技能',
          ultimate: '由任意两个高级技能触发时显示终式技能'
        };
        const bodyHtml = COMBO_GROUP_ORDER.map((groupKey) => {
          const slots = comboState.高级技能组配置[groupKey] || [];
          const slotHtml = Array.from({ length: 3 }, (_, index) => {
            const skillName = slots[index] || '';
            const skill = skillName ? (skillList[skillName] || {}) : null;
            const slotMeta = {
              comboSlot: true,
              section: 'advanced',
              groupKey,
              slotIndex: index,
              allowedTiers: ((COMBO_GROUP_SLOT_RULES[groupKey] || [])[index]) || [],
              title: `${COMBO_GROUP_LABELS[groupKey]}组技能槽 ${index + 1}`
            };
            const tierLabel = skillName
              ? `${skill?.类型 || '主动'} · ${skill?.阶位 || slotMeta.allowedTiers.join('/')}`
              : `可装备 ${slotMeta.allowedTiers.join('/') || '技能'}`;
            return `<button type="button" class="combo-config-slot" data-action="combo-config-slot" data-slot-meta='${encodeSlotMeta(slotMeta)}'>
              <span class="combo-config-slot-name${skillName ? '' : ' empty'}">${skillName || '点击装备技能'}</span>
              <span class="combo-config-slot-tier">${tierLabel}</span>
            </button>`;
          }).join('');
          return `<section class="combo-config-card${activeDisplayGroup === groupKey ? ' is-active' : ''}" data-config-group="${groupKey}">
            <div class="combo-config-head">
              <div class="combo-picker-avatar-placeholder combo-group-badge${groupKey === 'ultimate' ? ' is-ultimate' : ''}">${COMBO_GROUP_LABELS[groupKey]}</div>
              <div class="combo-config-meta">
                <div class="combo-config-title">${COMBO_GROUP_LABELS[groupKey]} 组</div>
                <div class="combo-config-desc">${groupDescriptions[groupKey] || ''}</div>
              </div>
            </div>
            <div class="combo-config-slot-row">${slotHtml}</div>
          </section>`;
        }).join('');
        const overlayHtml = `<div class="combo-picker-overlay" id="combo-config-overlay">
          <div class="combo-picker combo-group-config">
            <div class="combo-picker-title" style="color:var(--text-main)"><i class="ri-layout-grid-line"></i> 配置高级技能组</div>
            <div class="combo-group-config-body">${bodyHtml}</div>
          </div>
        </div>`;
