        const overlay = document.getElementById('combo-config-overlay');
        requestAnimationFrame(() => overlay?.classList.add('show'));
        if (focusGroupKey) {
          requestAnimationFrame(() => {
            overlay?.querySelector(`[data-config-group="${focusGroupKey}"]`)?.scrollIntoView({ block: 'nearest' });
          });
        }
        overlay?.addEventListener('click', (evt) => {
          if (evt.target === overlay) { overlay.remove(); return; }
          const slotBtn = evt.target.closest('[data-action="combo-config-slot"]');
          if (!slotBtn) return;
          const slotMetaRaw = slotBtn.dataset.slotMeta || '';
          const slotMeta = parseSlotMeta(slotMetaRaw);
          const latestState = getComboEquipState(fetchLatestMvuData());
          const currentSkillName = slotMeta
            ? ((latestState.高级技能组配置?.[slotMeta.groupKey] || [])[slotMeta.slotIndex] || '')
            : '';
          overlay.remove();
          openSkillPicker('', currentSkillName, slotMetaRaw);
        });
      }

      // ==================== 自动学习已解锁技能并装备到空槽位 ====================
      const autoLearnAndEquipSkills = async (data) => {
        const skillTree = data?.人物?.技能树;
        if (!skillTree || !skillTree.技能列表) return false;
        const charLevel = data?.人物?.等级 || 1;
        const skillList = skillTree.技能列表;
        const 人物 = data?.人物 || {};
        const skillSystemMode = getSkillSystemMode(data);
        if (!人物.主动技能槽) 人物.主动技能槽 = {};
        if (!人物.觉醒技能槽) 人物.觉醒技能槽 = {};
        const patches = [];
        const slotConfig = getSkillSlotConfig(data);
        const projectedSlotCounts = {
          主动技能槽: Object.keys(人物.主动技能槽 || {}).length,
          觉醒技能槽: Object.keys(人物.觉醒技能槽 || {}).length
        };

        Object.entries(skillList).forEach(([skillName, skill]) => {
          const tier = TIER_CONFIG[skill.阶位];
          if (!tier) return;
          const isUnlocked = charLevel >= tier.习得等级;
          const currentLevel = skill.当前等级 || 0;
          if (isUnlocked && currentLevel === 0) {
            // 自动学习：设为1级
            patches.push({ op: 'add', path: `/人物/技能树/技能列表/${skillName}/当前等级`, value: 1 });
            // 尝试自动装备到空槽位
            const isAwk = skill.阶位?.includes('觉醒');
            if (skillSystemMode === 'combo' && !isAwk) return;
            const slotKey = isAwk ? '觉醒技能槽' : '主动技能槽';
            const maxSlots = isAwk ? slotConfig.awakening : slotConfig.main;
            if (!人物[slotKey]?.[skillName]) {
              const equippedCount = projectedSlotCounts[slotKey] || 0;
              if (equippedCount < maxSlots) {
                patches.push({
                  op: 'add',
                  path: `/人物/${slotKey}/${skillName}`,
                  value: {
                    名称: skillName,
                    类型: skill.类型 || '主动',
                    技能等级: 1,
                    冷却中: false,
                    伤害倍率: calcSkillDamage({ ...skill, 当前等级: 1 }, data),
                    阶位: skill.阶位,
                    特殊效果: getSpecialEffectObj({ ...skill, 当前等级: 1 }),
                    描述: skill.描述 || ''
                  }
                });
                projectedSlotCounts[slotKey] = equippedCount + 1;
              }
            }
          }
        });
        if (patches.length > 0) {
          return await applyMvuPatchesAndWait(patches);
        }
        return false;
