      let _characterProfileEditorState = null;
      const showStatusNotice = (type, message, duration = 2400) => {
        const existing = document.getElementById('status-notice-toast');
        if (existing) existing.remove();
        const palette = {
          success: { bg: 'rgba(39, 174, 96, 0.95)', icon: 'ri-checkbox-circle-line' },
          error: { bg: 'rgba(233, 69, 96, 0.95)', icon: 'ri-close-circle-line' },
          warning: { bg: 'rgba(230, 126, 34, 0.96)', icon: 'ri-error-warning-line' },
          info: { bg: 'rgba(45, 52, 54, 0.95)', icon: 'ri-information-line' }
        };
        const style = palette[type] || palette.info;
        const el = document.createElement('div');
        el.id = 'status-notice-toast';
        el.style.cssText = `position:fixed;top:20px;left:50%;transform:translateX(-50%);background:${style.bg};color:#fff;padding:8px 16px;border-radius:10px;font-size:0.78rem;font-weight:700;z-index:1500;pointer-events:none;animation:fadeInOut 2.4s forwards;box-shadow:0 8px 20px rgba(0,0,0,0.24);display:flex;align-items:center;gap:8px;max-width:min(90vw,560px);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;`;
        el.innerHTML = `<i class="${style.icon}"></i><span>${escapeHtml(message || '')}</span>`;
        document.body.appendChild(el);
        setTimeout(() => el.remove(), duration);
      };

      function normalizeWorldbookKeywordList(values) {
        const source = Array.isArray(values) ? values : String(values || '').split(/[\n,，]/);
        const output = [];
        const seen = new Set();
        source.forEach((item) => {
          const text = String(item || '').trim();
          if (!text || seen.has(text)) return;
          seen.add(text);
          output.push(text);
        });
        return output;
      }

      function getCharacterProfileEntryName(name) {
        return `${CHARACTER_PROFILE_ENTRY_PREFIX}${String(name || '').trim()}`;
      }

      function stripYamlCodeFence(text) {
        let value = String(text || '').trim();
        value = value.replace(/^```ya?ml\s*/i, '').trim();
        value = value.replace(/```$/i, '').trim();
        return value;
      }

      function extractCharacterProfileYaml(content) {
        const raw = String(content || '').trim();
        if (!raw) return '';
        const tagPattern = new RegExp(`<${CHARACTER_PROFILE_RESPONSE_TAG}>([\\s\\S]*?)<\\/${CHARACTER_PROFILE_RESPONSE_TAG}>`, 'i');
        const tagMatch = raw.match(tagPattern);
        if (tagMatch && tagMatch[1]) {
          return stripYamlCodeFence(tagMatch[1]);
        }
        const yamlFenceMatch = raw.match(/```ya?ml\s*([\s\S]*?)```/i);
        if (yamlFenceMatch && yamlFenceMatch[1]) {
          return String(yamlFenceMatch[1]).trim();
        }
        const yamlStart = raw.indexOf('---');
        if (yamlStart >= 0) {
          return raw.slice(yamlStart).trim();
        }
        return '';
      }

      function normalizeCharacterProfileAiResponse(result) {
        if (typeof result === 'string') return result;
        if (Array.isArray(result)) {
          return result.map(normalizeCharacterProfileAiResponse).filter(Boolean).join('\n');
        }
        const candidates = [
          result?.message,
          result?.content,
          result?.text,
          result?.response,
          result?.data?.content,
          result?.data?.text,
          result?.choices?.[0]?.message?.content,
          result?.choices?.[0]?.text
        ];
        const resolved = candidates.find((item) => typeof item === 'string' && item.trim());
        return resolved || String(result || '');
      }

      function clonePromptData(value) {
        try {
          return JSON.parse(JSON.stringify(value ?? {}));
        } catch (e) {
          return value ?? {};
        }
      }

      function createCharacterProfileWorldbookDriver() {
        const required = [
          typeof getWorldbookNames === 'function',
          typeof getWorldbook === 'function',
          typeof updateWorldbookWith === 'function',
          typeof createWorldbookEntries === 'function'
        ];
        if (required.some((available) => !available)) {
          return null;
        }
        return {
          async getContext() {
            const charWorldbooksRaw = typeof getCharWorldbookNames === 'function'
              ? getCharWorldbookNames('current')
              : null;
            return {
              worldbookNames: typeof getWorldbookNames === 'function' ? (getWorldbookNames() || []) : [],
              globalWorldbooks: typeof getGlobalWorldbookNames === 'function' ? (getGlobalWorldbookNames() || []) : [],
              chatWorldbook: typeof getChatWorldbookName === 'function' ? (getChatWorldbookName('current') || '') : '',
              charWorldbooks: {
                primary: charWorldbooksRaw?.primary || '',
                additional: Array.isArray(charWorldbooksRaw?.additional) ? charWorldbooksRaw.additional.filter(Boolean) : []
              }
            };
          },
          async getEntries(worldbookName) {
            return await getWorldbook(worldbookName);
          },
          async createEntries(worldbookName, entries) {
            return await createWorldbookEntries(worldbookName, entries, { render: 'immediate' });
          },
          async updateEntry(worldbookName, uid, nextEntry) {
            return await updateWorldbookWith(worldbookName, (worldbook) => worldbook.map((entry) => (
              Number(entry.uid) === Number(uid) ? { ...entry, ...nextEntry } : entry
            )), { render: 'immediate' });
          },
          async deleteEntries(worldbookName, predicate) {
            return await updateWorldbookWith(
              worldbookName,
              (worldbook) => (Array.isArray(worldbook) ? worldbook.filter((entry) => !predicate(entry)) : worldbook),
              { render: 'immediate' }
            );
          }
        };
      }

      async function resolveCharacterProfileWorldbook(driver) {
        const context = await driver.getContext();
        return context?.charWorldbooks?.primary
          || context?.chatWorldbook
          || context?.charWorldbooks?.additional?.[0]
          || context?.globalWorldbooks?.[0]
          || context?.worldbookNames?.[0]
          || '';
      }

      function pickCharacterProfileOrder(entries, ignoreUid = null) {
        const usedInRange = new Set();
        let maxOrder = CHARACTER_PROFILE_ORDER_END;
        (Array.isArray(entries) ? entries : []).forEach((entry) => {
          if (!entry || Number(entry.uid) === Number(ignoreUid)) return;
          const positionType = String(entry?.position?.type || '');
          const order = Number(entry?.position?.order);
          if (positionType !== 'after_character_definition' || !Number.isFinite(order)) return;
          if (order >= CHARACTER_PROFILE_ORDER_START && order <= CHARACTER_PROFILE_ORDER_END) {
            usedInRange.add(order);
          }
          if (order > maxOrder) maxOrder = order;
        });
        for (let order = CHARACTER_PROFILE_ORDER_START; order <= CHARACTER_PROFILE_ORDER_END; order++) {
          if (!usedInRange.has(order)) return order;
        }
        return maxOrder + 1;
      }

      function createCharacterProfileWorldbookEntryPayload({ name, content, keywords, order }) {
        const normalizedKeywords = normalizeWorldbookKeywordList(keywords);
        return {
          name: getCharacterProfileEntryName(name),
          enabled: true,
          strategy: {
            type: normalizedKeywords.length > 0 ? 'selective' : 'constant',
            keys: normalizedKeywords,
            keys_secondary: { logic: 'and_any', keys: [] },
            scan_depth: 'same_as_global'
          },
          position: {
            type: 'after_character_definition',
            role: 'system',
            depth: 0,
            order
          },
          content: String(content || '').trim(),
          probability: 100,
          recursion: {
            prevent_incoming: true,
            prevent_outgoing: true,
            delay_until: null
          },
          effect: {
            sticky: null,
            cooldown: null,
            delay: null
          },
          extra: {
            characterProfileGenerator: {
              sourceName: String(name || '').trim(),
              installedAt: new Date().toISOString()
            }
          }
        };
      }

      async function saveCharacterProfileToWorldbook({ name, content, keywords }) {
        const driver = createCharacterProfileWorldbookDriver();
        if (!driver) {
          throw new Error('当前环境未提供世界书写入接口');
        }
        const worldbookName = await resolveCharacterProfileWorldbook(driver);
        if (!worldbookName) {
          throw new Error('当前没有可写入的目标世界书');
        }
        const entries = await driver.getEntries(worldbookName);
        const entryName = getCharacterProfileEntryName(name);
        const existing = (Array.isArray(entries) ? entries : []).find((entry) => {
          const sameName = String(entry?.name || '').trim() === entryName;
          const sameSource = String(entry?.extra?.characterProfileGenerator?.sourceName || '').trim() === String(name || '').trim();
          return sameName || sameSource;
        });
        const order = pickCharacterProfileOrder(entries, existing?.uid);
        const payload = createCharacterProfileWorldbookEntryPayload({ name, content, keywords, order });
        if (existing) {
          await driver.updateEntry(worldbookName, existing.uid, {
            ...existing,
            ...payload,
            extra: {
              ...(existing.extra || {}),
              ...(payload.extra || {})
            }
          });
        } else {
          await driver.createEntries(worldbookName, [payload]);
        }
        return { worldbookName, order, updated: !!existing };
      }

      function shouldInlineCharacterProfileChatReference() {
        const targetWindow = getParent();
        const phoneApiConfig = targetWindow.phoneForumManager?.apiConfig;
        return !!(phoneApiConfig && phoneApiConfig.isAvailable());
      }

      function getCharacterProfileChatData() {
        try {
          const targetWindow = getParent();
          if (targetWindow.SillyTavern && typeof targetWindow.SillyTavern.getContext === 'function') {
            const ctx = targetWindow.SillyTavern.getContext();
            if (ctx && Array.isArray(ctx.chat) && ctx.chat.length > 0) {
              return { characterName: ctx.name2 || '角色', messages: ctx.chat };
            }
          }
          if (targetWindow.context && Array.isArray(targetWindow.context.chat) && targetWindow.context.chat.length > 0) {
            return { characterName: targetWindow.context.name2 || '角色', messages: targetWindow.context.chat };
          }
        } catch (e) { }
        return null;
