      function buildCharacterProfileChatReferenceSection() {
        const chatData = getCharacterProfileChatData();
        if (!chatData || !Array.isArray(chatData.messages) || chatData.messages.length === 0) return '';
        const recentMessages = chatData.messages.slice(-25);
        const lines = recentMessages.map((msg) => {
          const content = String(msg?.mes || '').trim();
          if (!content) return '';
          const role = msg?.is_user ? '玩家' : (msg?.name || chatData.characterName || '角色');
          return `**${role}**: ${content}`;
        }).filter(Boolean);
        if (lines.length === 0) return '';
        return `

参考以下剧情内容定位角色形象。你应结合这些近期互动、言行与处境，补充角色的说话方式、行为倾向、关系状态与当前氛围；如果与“当前已知角色信息”冲突，仍以“当前已知角色信息”为准。

近期剧情内容参考：
\`\`\`markdown
${lines.join('\n\n')}
\`\`\``;
      }

