        if (phoneApiConfig && phoneApiConfig.isAvailable()) {
          const result = await phoneApiConfig.callAPI([{ role: 'user', content: prompt }], false, '');
          return normalizeCharacterProfileAiResponse(result);
        }
        if (targetWindow.TavernHelper && targetWindow.TavernHelper.generateRaw) {
          const result = await targetWindow.TavernHelper.generateRaw({
            ordered_prompts: [
