              <div class="f-mini-stat"><span class="f-ms-label">等级</span><span class="f-ms-val">${level} <span style="font-size:0.8em;opacity:0.6">/ ${maxLevel}</span></span></div>
              <div class="f-mini-stat"><span class="f-ms-label">阶位</span><span class="f-ms-val" style="color:${tierColor}">${tier}</span></div>
              <div class="f-mini-stat"><span class="f-ms-label">解锁</span><span class="f-ms-val" style="color:${isUnlocked ? '#27ae60' : '#e74c3c'}">${isUnlocked ? '✓' : 'Lv.' + requiredLevel}</span></div>
            </div>
            <div class="f-content">
              <div class="f-data-group">
                ${spCost > 0 ? `<div class="f-data-row"><span class="f-data-label"><i class="ri-star-line"></i> SP消耗/级</span><span class="f-data-val">${spCost}</span></div>` : ''}
                ${cd > 0 ? `<div class="f-data-row"><span class="f-data-label"><i class="ri-timer-line"></i> 冷却</span><span class="f-data-val">${cd} 回合</span></div>` : ''}
                ${dmg > 0 ? `<div class="f-data-row"><span class="f-data-label"><i class="ri-sword-line"></i> 伤害倍率</span><span class="f-data-val val-positive">${dmg}%</span></div>` : ''}
              </div>
              <div class="f-section-title"><i class="ri-file-text-line"></i> 描述</div>
              <div class="f-effect-box">${desc || '无'}</div>
              ${special ? `<div class="f-section-title"><i class="ri-magic-line"></i> 当前效果 (Lv.${level})</div><div class="f-effect-box">${special}</div>` : ''}
            </div>
            ${(canManageSlot || canManageComboSlot) ? `<div style="display:flex;gap:8px;padding:12px 16px;border-top:1px solid #f0f0f0;">
              <button class="skill-action-btn skill-unequip" style="flex:1;padding:8px;border:1px solid #e0e0e0;border-radius:8px;background:#fff;cursor:pointer;font-size:0.75rem;color:#e74c3c;font-weight:600;">
                <i class="ri-delete-back-2-line"></i> 卸下
              </button>
              ${(canManageSlot || canManageComboSlot) && availableOthers.length > 0 ? `<button class="skill-action-btn skill-change" style="flex:1;padding:8px;border:1px solid #dfe6e9;border-radius:8px;background:#f8f9fa;cursor:pointer;font-size:0.75rem;color:var(--text-main);font-weight:600;">
                <i class="ri-refresh-line"></i> 更换
              </button>` : ''}
            </div>` : ''}
          </div>
        </div>`;
        app.insertAdjacentHTML('afterend', html);
        // 卸下
        if (canManageSlot || canManageComboSlot) {
          document.querySelector('.skill-unequip')?.addEventListener('click', () => {
            // 战斗中禁止更换技能
            if (isInBattle()) { showBattleWarning('战斗中无法更换技能'); return; }
            if (canManageComboSlot) {
              const ok = setComboSlotAssignment(slotMeta, '');
              if (!ok) return;
              removePopup();
              setTimeout(refresh, 100);
              return;
            }
            applyMvuPatches([
              { op: 'remove', path: `/人物/${slotType}/${skillName}` },
              // 同步更新技能列表中的是否装备状态
              { op: 'replace', path: `/人物/技能树/技能列表/${skillName}/是否装备`, value: false }
            ]);
            removePopup();
            setTimeout(refresh, 100);
          });
        }
        if (canManageSlot || canManageComboSlot) {
          document.querySelector('.skill-change')?.addEventListener('click', () => {
            // 战斗中禁止更换技能
            if (isInBattle()) { showBattleWarning('战斗中无法更换技能'); return; }
            removePopup();
            openSkillPicker(slotType, skillName, slotMetaRaw);
          });
        }
        bindPopupClose();
      };


      const clearEquippedSkillSlot = (slotType, replaceSkillName, slotMetaRaw) => {
        if (!replaceSkillName) return false;
        if (isInBattle()) { showBattleWarning('战斗中无法更换技能'); return false; }
        const slotMeta = parseSlotMeta(slotMetaRaw);
        if (slotMeta && slotMeta.comboSlot) {
          const ok = setComboSlotAssignment(slotMeta, '');
          if (ok) setTimeout(refresh, 100);
          return ok;
        }
        if (!slotType) return false;
        applyMvuPatches([
          { op: 'remove', path: `/人物/${slotType}/${replaceSkillName}` },
          { op: 'replace', path: `/人物/技能树/技能列表/${replaceSkillName}/是否装备`, value: false }
        ]);
        setTimeout(refresh, 100);
        return true;
      };

      // 技能选择器
      const openSkillPicker = (slotType, replaceSkillName, slotMetaRaw) => {
        document.getElementById('combo-picker-overlay')?.remove();
        const d = fetchLatestMvuData();
        const skillTree = d?.人物?.技能树 || {};
        const 技能列表 = skillTree.技能列表 || {};
        const slotMeta = parseSlotMeta(slotMetaRaw);
        const equippedAll = new Set([
          ...Object.keys(d?.人物?.主动技能槽 || {}),
          ...Object.keys(d?.人物?.觉醒技能槽 || {})
        ]);
        const isAwk = slotType === '觉醒技能槽';
        const awkTiers = new Set(['觉醒一', '觉醒二', '觉醒三']);

        const charLevel = d?.人物?.等级 || 1;
        let available = [];
        if (slotMeta && slotMeta.comboSlot) {
          const comboState = getComboEquipState(d);
          const activeNames = new Set(getComboActiveSkillNames(comboState, slotMeta.groupKey));
          if (replaceSkillName) activeNames.delete(replaceSkillName);
          available = Object.entries(技能列表).filter(([name, skill]) => {
            if (name === replaceSkillName) return false;
            if (activeNames.has(name)) return false;
            if ((skill?.当前等级 || 0) === 0) return false;
            const tierCfg = TIER_CONFIG[skill.阶位 || ''];
            if (tierCfg && charLevel < tierCfg.习得等级) return false;
            return (slotMeta.allowedTiers || []).includes(skill.阶位 || '');
          });
        } else {
          available = Object.entries(技能列表).filter(([name, skill]) => {
            if (equippedAll.has(name)) return false;
            const t = skill.阶位 || '基础';
            if (isAwk ? !awkTiers.has(t) : awkTiers.has(t)) return false;
            // 只显示当前等级已解锁的技能
            const tierCfg = TIER_CONFIG[t];
            if (tierCfg && charLevel < tierCfg.习得等级) return false;
            // 只显示已学习的技能（等级 > 0）
            if ((skill.当前等级 || 0) === 0) return false;
            return true;
          });
        }

        const canClearCurrent = !!replaceSkillName && (!!slotType || (slotMeta && slotMeta.comboSlot));
        if (available.length === 0 && !canClearCurrent) {
          showBattleWarning((slotMeta && slotMeta.comboSlot) ? `${slotMeta.title} 没有可装备技能` : '当前没有可装备技能');
          return;
        }

        const pickerSlotMetaAttr = slotMeta ? (" data-slot-meta='" + encodeSlotMeta(slotMeta) + "'") : '';
        let listHtml = '';
        if (canClearCurrent) {
          const clearSlotLabel = (slotMeta && slotMeta.comboSlot)
            ? (slotMeta.title || '当前槽位')
            : (isAwk ? '当前觉醒槽位' : '当前技能槽');
          listHtml += `<div class="combo-picker-item current" data-clear-skill-slot="1" data-slot-type="${slotType || ''}" data-replace-skill="${replaceSkillName}"${pickerSlotMetaAttr}>
            <div class="combo-picker-avatar-placeholder" style="background:#fff5f5;color:#c0392b;">
              <i class="ri-delete-back-2-line"></i>
            </div>
            <div class="combo-picker-info">
              <div class="combo-picker-bond-name">卸下当前技能</div>
              <div class="combo-picker-skill-name" style="color:#c0392b">${replaceSkillName} · ${clearSlotLabel}</div>
            </div>
          </div>`;
        }
        available.forEach(([name, skill]) => {
          const tier = skill.阶位 || '基础';
          const tierColor = tierColors[tier] || '#95a5a6';
          const lv = skill.当前等级 || 0;
          const typeStr = skill.类型 || '主动';
          const iconSvg = getSkillSvg(typeStr, tier);
          listHtml += `<div class="combo-picker-item" data-equip-skill="${name}" data-slot-type="${slotType}"${pickerSlotMetaAttr}>
            <div style="width:32px;height:32px;display:flex;align-items:center;justify-content:center;flex-shrink:0;color:${tierColor};">${iconSvg}</div>
            <div class="combo-picker-info">
              <div class="combo-picker-bond-name">${name}</div>
              <div class="combo-picker-skill-name" style="color:var(--text-sub)">${typeStr} · ${tier} · Lv.${lv}</div>
            </div>
          </div>`;
        });

        const allowedTierLabel = (slotMeta && slotMeta.allowedTiers) ? slotMeta.allowedTiers.join('/') : '';
        const title = (slotMeta && slotMeta.comboSlot)
          ? `选择${allowedTierLabel || ''}技能`
          : (isAwk ? '选择觉醒技能' : '选择技能');
        const overlayHtml = `<div class="combo-picker-overlay" id="combo-picker-overlay">
          <div class="combo-picker">
            <div class="combo-picker-title" style="color:var(--text-main)"><i class="ri-sword-line"></i> ${title}</div>
            <div class="combo-picker-list">${listHtml}</div>
          </div>
        </div>`;
        document.body.insertAdjacentHTML('beforeend', overlayHtml);
        const overlay = document.getElementById('combo-picker-overlay');
        requestAnimationFrame(() => overlay?.classList.add('show'));
        overlay?.addEventListener('click', (e) => {
          if (e.target === overlay) { overlay.remove(); return; }
          const clearItem = e.target.closest('[data-clear-skill-slot]');
          if (clearItem) {
            const cleared = clearEquippedSkillSlot(clearItem.dataset.slotType, clearItem.dataset.replaceSkill, clearItem.dataset.slotMeta);
            if (cleared) overlay.remove();
            return;
          }
          const item = e.target.closest('[data-equip-skill]');
          if (!item) return;
          const equipped = equipSkillToSlot(item.dataset.equipSkill, item.dataset.slotType, replaceSkillName, item.dataset.slotMeta);
          if (equipped) overlay.remove();
        });
      };

      const equipSkillToSlot = (skillName, slotType, replaceSkillName, slotMetaRaw) => {
        // 战斗中禁止更换技能
        if (isInBattle()) { showBattleWarning('战斗中无法更换技能'); return false; }
        const d = fetchLatestMvuData();
        const skill = d?.人物?.技能树?.技能列表?.[skillName] || {};
        const slotMeta = parseSlotMeta(slotMetaRaw);
        if (slotMeta && slotMeta.comboSlot) {
          const ok = setComboSlotAssignment(slotMeta, skillName);
          if (!ok) return false;
          setTimeout(refresh, 100);
          return true;
        }
        const slotConfig = getSkillSlotConfig(d);
        const isAwk = slotType === '觉醒技能槽';
        const maxSlots = isAwk ? slotConfig.awakening : slotConfig.main;
        const currentCount = Object.keys(d?.人物?.[slotType] || {}).length;
        if (!replaceSkillName && currentCount >= maxSlots) {
          showBattleWarning(`${isAwk ? '觉醒' : '主动'}技能槽已满`);
          return false;
        }
        const slotData = {
          名称: skillName,
          类型: skill.类型 || '主动',
          技能等级: skill.当前等级 || 1,
          冷却中: false,
          伤害倍率: calcSkillDamage({ ...skill, 当前等级: skill.当前等级 || 1 }, d),
          阶位: skill.阶位 || '基础',
          特殊效果: getSpecialEffectObj({ ...skill, 当前等级: skill.当前等级 || 1 }),
          描述: skill.描述 || ''
        };
        if (skill.召唤物名称) slotData.召唤物名称 = skill.召唤物名称;
        const patches = [];
        if (replaceSkillName) {
          patches.push({ op: 'remove', path: `/人物/${slotType}/${replaceSkillName}` });
          // 同步更新被替换技能的是否装备状态
          patches.push({ op: 'replace', path: `/人物/技能树/技能列表/${replaceSkillName}/是否装备`, value: false });
        }
        patches.push({ op: 'add', path: `/人物/${slotType}/${skillName}`, value: slotData });
        // 同步更新技能列表中的是否装备状态
        patches.push({ op: 'replace', path: `/人物/技能树/技能列表/${skillName}/是否装备`, value: true });
        const applied = applyMvuPatches(patches);
        if (!applied) {
          showBattleWarning('技能装备失败：MVU 数据未就绪');
          return false;
        }
        setTimeout(refresh, 100);
        return true;
      };

      const getDataUrlByteSize = (dataUrl) => {
        try {
          const base64 = String(dataUrl || '').split(',')[1] || '';
          return Math.ceil(base64.length * 3 / 4);
        } catch (e) {
          return Number.MAX_SAFE_INTEGER;
        }
      };

      const compressAvatarImage = (file, opts = {}) => new Promise((resolve, reject) => {
        if (!file) return reject(new Error('no_file'));
        const maxSide = opts.maxSide || 512;
        const maxBytes = opts.maxBytes || 240 * 1024;
        const minQuality = opts.minQuality || 0.5;
        let quality = opts.quality || 0.85;

        const reader = new FileReader();
        reader.onerror = () => reject(new Error('read_failed'));
        reader.onload = () => {
          const img = new Image();
          img.onerror = () => reject(new Error('decode_failed'));
          img.onload = () => {
            const longest = Math.max(img.width, img.height) || 1;
            const scale = Math.min(1, maxSide / longest);
            const targetW = Math.max(1, Math.round(img.width * scale));
            const targetH = Math.max(1, Math.round(img.height * scale));
            const canvas = document.createElement('canvas');
            canvas.width = targetW;
            canvas.height = targetH;
            const ctx = canvas.getContext('2d');
            if (!ctx) return reject(new Error('canvas_failed'));
            ctx.drawImage(img, 0, 0, targetW, targetH);

            let out = canvas.toDataURL('image/jpeg', quality);
            while (getDataUrlByteSize(out) > maxBytes && quality > minQuality) {
              quality = Math.max(minQuality, quality - 0.1);
              out = canvas.toDataURL('image/jpeg', quality);
            }
            resolve(out);
          };
          img.src = String(reader.result || '');
        };
        reader.readAsDataURL(file);
      });

      // 暴露给 window 以便 innerHTML onclick 调用
      window.triggerAvatarUpload = (name) => {
        const input = document.createElement('input');
        input.type = 'file';
        input.accept = 'image/*';
        input.onchange = async (e) => {
          const file = e.target.files[0];
          if (!file) return;
          try {
            const base64 = await compressAvatarImage(file, { maxSide: 512, maxBytes: 240 * 1024, quality: 0.85, minQuality: 0.5 });
            // 仅持久化到 localStorage，不写入 MVU
            localStorage.setItem('rpg_bond_avatar_' + name, base64);
            _cachedData = null;
            setTimeout(refresh, 100);
          } catch (err) {
            console.warn('羁绊头像处理失败:', err);
          }
        };
        input.click();
      };

      // 统一获取羁绊头像：localStorage > MVU > 预设
      const getBondAvatar = (name, bond) => {
        try { const v = localStorage.getItem('rpg_bond_avatar_' + name); if (v) return v; } catch (e) { }
        return bond?.头像 || getPresetAvatar(name) || '';
      };

      // 清理不再存在的羁绊头像缓存，防止 localStorage 泄漏
      const cleanBondAvatarCache = (currentBondNames) => {
        try {
          const prefix = 'rpg_bond_avatar_';
          const keysToRemove = [];
          for (let i = 0; i < localStorage.length; i++) {
            const key = localStorage.key(i);
            if (key && key.startsWith(prefix)) {
              const name = key.slice(prefix.length);
              if (!currentBondNames.has(name)) keysToRemove.push(key);
            }
          }
          keysToRemove.forEach(k => localStorage.removeItem(k));
        } catch (e) { }
      };

      // 玩家主角头像上传
      window.triggerPlayerAvatarUpload = () => {
        const input = document.createElement('input');
        input.type = 'file';
        input.accept = 'image/*';
        input.onchange = async (e) => {
          const file = e.target.files[0];
          if (!file) return;
          try {
            const base64 = await compressAvatarImage(file, { maxSide: 512, maxBytes: 240 * 1024, quality: 0.85, minQuality: 0.5 });
            localStorage.setItem('rpg_player_avatar', base64);
            _cachedData = null;
            setTimeout(refresh, 100);
          } catch (err) {
            console.warn('头像处理失败:', err);
          }
        };
        input.click();
      };

      // 渲染羁绊详情到右侧面板
      // 渲染羁绊详情到右侧面板 (Bento Layout)
      let bondUpgradeBusy = false;
      const renderBondDetail = (name, data) => {
        const container = document.getElementById('bond-container');
        const pane = document.getElementById('bond-detail-container');
        if (!pane || !container) return;

        // 品质颜色映射
        const qualityColorMap = {
          '普通': '#2D3436',
          '精良': '#0047AB',
          '稀有': '#9b59b6',
          '卓越': '#e84393',
          '传说': '#e67e22',
          '史诗': '#C9A227',
          '神话': '#e8198b'
        };
        const getQualityColor = (q) => qualityColorMap[normalizeQualityName(q)] || qualityColorMap['普通'];
        const qualityBadgeMap = {
          '普通': { bg: 'rgba(45, 52, 54, 0.08)', color: '#636e72', border: 'rgba(45, 52, 54, 0.12)' },
          '精良': { bg: 'rgba(0, 71, 171, 0.08)', color: '#0047AB', border: 'rgba(0, 71, 171, 0.15)' },
          '稀有': { bg: 'rgba(155, 89, 182, 0.08)', color: '#9b59b6', border: 'rgba(155, 89, 182, 0.15)' },
          '卓越': { bg: 'rgba(232, 67, 147, 0.08)', color: '#e84393', border: 'rgba(232, 67, 147, 0.15)' },
          '传说': { bg: 'rgba(230, 126, 34, 0.08)', color: '#e67e22', border: 'rgba(230, 126, 34, 0.15)' },
          '史诗': { bg: 'rgba(201, 162, 39, 0.08)', color: '#C9A227', border: 'rgba(201, 162, 39, 0.15)' },
          '神话': { bg: 'rgba(232, 25, 139, 0.08)', color: '#e8198b', border: 'rgba(232, 25, 139, 0.15)' }
        };
        const getQualityBadgeStyle = (q) => q ? (qualityBadgeMap[normalizeQualityName(q)] || null) : null;

        container.classList.add('mode-detail'); // 切换到紧凑模式

        const gender = data.性别 || '未知';
        const race = data.种族 || '未知';
        const level = data.等级 || 1;
        const stats = data.属性 || {};
        const skills = data.技能 || {};
        const equips = data.装备列表 || {};
        const comboSkills = data.连携奥义 || {};
        const avatar = getBondAvatar(name, data);
        const favor = data.好感度 || 0;
        const favorMax = 100;
        const favorPct = Math.min(100, Math.max(0, ((favor + favorMax) / (favorMax * 2)) * 100));
        const detailVisible = isBondDetailVisible(fetchLatestMvuData(), name);
        const isSeaBond = fetchLatestMvuData()?.系统配置?.世界观 === '诡秘地海';

        const fmtNum = (n) => Number.isFinite(n)
          ? (Math.abs(n - Math.round(n)) < 0.001 ? String(Math.round(n)) : String(Math.round(n * 10) / 10))
          : '0';

        const hpCurrent = Number(data.当前生命值);
        const hpMax = Number(data.生命值上限);
        const hasHpBar = Number.isFinite(hpCurrent) && Number.isFinite(hpMax) && hpMax > 0;
        const safeHpCurrent = hasHpBar ? Math.min(Math.max(hpCurrent, 0), hpMax) : 0;
        const hpPct = hasHpBar ? Math.min(100, Math.max(0, (safeHpCurrent / hpMax) * 100)) : 0;

        const bondSanMax = Number(data.理智值上限);
        const bondSanCurrent = Number(data.理智值);
        const hasBondSan = isSeaBond && Number.isFinite(bondSanMax) && bondSanMax > 0 && Number.isFinite(bondSanCurrent);
        const safeBondSan = hasBondSan ? Math.min(Math.max(Math.floor(bondSanCurrent), 0), Math.floor(bondSanMax)) : 0;
        const bondSanPct = hasBondSan ? safeBondSan / bondSanMax * 100 : 0;

        const expCurrent = Number(data.当前总经验);
        const safeExpCurrent = Number.isFinite(expCurrent) ? Math.max(0, Math.floor(expCurrent)) : 0;
        const safeLevel = Math.min(100, Math.max(1, Math.floor(Number(level) || 1)));
        const calcTh = (lv) => { let t = 0; for (let L = 1; L < lv; L++) t += Math.floor(100 * Math.pow(L, 1.5)); return t; };
        const poolValue = Number(fetchLatestMvuData()?.队友成长?.经验池?.[name]);
        const expPool = Number.isFinite(poolValue) ? Math.max(0, Math.floor(poolValue)) : 0;
        const upgradeCost = Math.max(0, calcTh(safeLevel + 1) - Math.max(calcTh(safeLevel), safeExpCurrent));
        const maxLevel = safeLevel >= 100;
        const canUpgrade = !maxLevel && expPool >= upgradeCost;
        const poolPct = maxLevel || upgradeCost === 0 ? 100 : Math.min(100, expPool / upgradeCost * 100);

        const resourceCardHTML = `
                <div class="bd-card bd-resource-card">
                  <div class="bd-card-title"><i class="ri-heart-pulse-line"></i> 状态</div>
                  <div class="bd-resource-grid">
                    ${hasHpBar ? `
                      <div class="bd-resource-row">
                        <div class="bd-resource-top">
                          <span class="bd-resource-name"><i class="ri-heart-3-line"></i>HP</span>
                          <span class="bd-resource-value">${fmtNum(safeHpCurrent)} / ${fmtNum(hpMax)}</span>
                        </div>
                        <div class="bd-resource-track"><div class="bd-resource-fill hp" style="width:${hpPct}%"></div></div>
                      </div>
                    ` : ''}
                    ${hasBondSan ? `
                      <div class="bd-resource-row">
                        <div class="bd-resource-top">
                          <span class="bd-resource-name"><i class="ri-mental-health-line"></i>SAN</span>
                          <span class="bd-resource-value">${fmtNum(safeBondSan)} / ${fmtNum(bondSanMax)}</span>
                        </div>
                        <div class="bd-resource-track"><div class="bd-resource-fill san" style="width:${bondSanPct}%"></div></div>
                      </div>
                    ` : ''}
                      <div class="bd-resource-row bd-growth-row">
                        <div class="bd-resource-top">
                          <span class="bd-resource-name"><i class="ri-inbox-archive-line"></i>经验池</span>
                          <span class="bd-resource-value bd-growth-pool">${fmtNum(expPool)}</span>
                        </div>
                        <div class="bd-resource-track"><div class="bd-resource-fill exp" style="width:${poolPct}%"></div></div>
                        <div class="bd-growth-footer">
                          <span class="bd-growth-cost">${maxLevel ? 'Lv.100 · 已满级' : `Lv.${safeLevel} → ${safeLevel + 1} · 需要 ${fmtNum(upgradeCost)}`}</span>
                          <button type="button" class="bd-growth-upgrade" data-bond-upgrade="${encodeURIComponent(name)}" ${canUpgrade && !bondUpgradeBusy ? '' : 'disabled'}>${maxLevel ? '已满级' : canUpgrade ? '升级' : '经验不足'}</button>
