        const cocSanCostByQuality = { 普通: 2, 精良: 4, 稀有: 6, 卓越: 8, 传说: 10, 史诗: 12, 神话: 15 };
        const cocSpellCost = Object.values(人物.资源技能 || {}).reduce((sum, skill) => {
