        const hasSkills = true;

        // 连携奥义技能槽渲染（单槽，可切换）
        const comboDefaultSvg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" class="combo-svg-icon"><path d="M0 0h512v512H0z" fill="transparent"></path><g transform="translate(0,0)"><path d="M370.803 299.826c-5.82-6.27-9.52-15.655-9.52-26.135 0-18.86 11.98-34.172 26.74-34.172 14.76 0 26.74 15.312 26.74 34.172 0 10.48-3.7 19.865-9.52 26.135 22.54 9.514 38.87 37.201 38.87 69.836 0 7.677-.9 15.08-2.58 22.033h-18.76l-4.84 86.485h-59.82l-4.84-86.485h-18.77c-1.67-6.953-2.58-14.356-2.58-22.033 0-32.635 16.33-60.322 38.88-69.836zm-264.05 0c-5.82-6.27-9.52-15.655-9.52-26.135 0-18.86 11.99-34.172 26.74-34.172 14.76 0 26.74 15.312 26.74 34.172 0 10.48-3.7 19.865-9.52 26.135 22.55 9.514 38.88 37.201 38.88 69.836 0 7.677-.91 15.08-2.58 22.033h-18.77l-4.83 86.485h-59.83l-4.83-86.485h-18.77c-1.68-6.953-2.58-14.356-2.58-22.033 0-32.635 16.33-60.322 38.87-69.836zm202.43-156.338 41.78 45.309-94.96 92.421-29.74-28.941 76.44-57.99-10.07-13.278-78.45 59.512-17.71-17.238zm-67.61 27.44-57.25 40.534-23.29-22.665 41.79-45.309zm237.69-143.565c-2.08 12.875-13.5 21.964-25.9 28.838-21.67 12.003-47.57 16.695-47.57 16.695l-8.2 1.49 2.98 16.398 8.2-1.49s26.29-4.789 49.59-16.867c-3.48 10.913-13.84 18.89-25 25.074-21.67 12.003-47.57 16.696-47.57 16.696l-8.2 1.489 2.98 16.399 8.2-1.49s16.77-3.056 35.39-10.439c-4.84 7.576-13.07 13.509-21.8 18.345-19.22 10.649-41.78 15.544-46.62 16.512l-28.87-28.064c45.55-28.633-2.99-94.227 152.39-99.586zm-446.52 0c2.08 12.875 13.49 21.964 25.9 28.838 21.66 12.003 47.56 16.695 47.56 16.695l8.2 1.49-2.98 16.398-8.2-1.49s-26.29-4.789-49.59-16.867c3.49 10.913 13.84 18.89 25.01 25.074 21.66 12.003 47.56 16.696 47.56 16.696l8.2 1.489-2.98 16.399-8.2-1.49s-16.77-3.056-35.39-10.439c4.84 7.576 13.08 13.509 21.81 18.345 19.22 10.649 41.77 15.544 46.61 16.512l28.88-28.064c-45.55-28.633 2.99-94.227-152.39-99.586zm223.26 36.178c15.67 0 28.39 18.768 28.39 41.885 0 23.116-12.72 41.884-28.39 41.884s-28.39-18.768-28.39-41.884c0-23.117 12.72-41.885 28.39-41.885z" fill="#b8860b" fill-opacity="1"></path></g></svg>`;

        // 收集所有有连携奥义的伙伴
        const allCombos = [];
        Object.entries(羁绊列表).forEach(([bondName, bond]) => {
          const comboSkills = bond.连携奥义 || {};
          Object.entries(comboSkills).forEach(([skillName, skillData]) => {
            allCombos.push({ bondName, skillName, skillData, avatar: getBondAvatar(bondName, bond) });
          });
        });

        // 读取已保存的选择
        const savedCombo = 人物.连携奥义槽 || {};
        let comboFound = null;
        if (savedCombo.伙伴 && savedCombo.技能名) {
          comboFound = allCombos.find(c => c.bondName === savedCombo.伙伴 && c.skillName === savedCombo.技能名);
        }

        let comboHTML = '';
        if (comboFound) {
          const { bondName, skillName, skillData, avatar } = comboFound;
          const dName = skillName.length > 4 ? skillName.slice(0, 4) + '…' : skillName;
          const iconContent = avatar
            ? `<img class="combo-avatar-icon" src="${avatar}" alt="${bondName}">`
            : comboDefaultSvg;
          const cpFull = CP >= 100;
          const cpFillCls = cpFull ? 'combo-cp-fill cp-full' : 'combo-cp-fill';
          const cpPct = Math.min(100, Math.max(0, CP));
          comboHTML = `<div class="skill-slot-wrapper">
            <div class="skill-slot combo-ultimate active" data-skill="${skillName}" data-bond="${bondName}" data-combo-info='${JSON.stringify({ 名称: skillName, 伙伴: bondName, ...skillData }).replace(/'/g, "&#39;")}'>
              <div class="skill-icon">${iconContent}</div>
              <div class="${cpFillCls}" style="height:${cpPct}%"></div>
            </div>
            <div class="skill-slot-name combo-name">${dName}</div>
            <div class="skill-tooltip">${skillName}（${bondName}）</div>
          </div>`;
        } else {
          comboHTML = `<div class="skill-slot-wrapper"><div class="skill-slot combo-ultimate empty" data-action="combo-pick" style="cursor:pointer">
            <div class="skill-icon">${comboDefaultSvg}</div>
          </div></div>`;
        }
        const awakeningRowHTML = renderSlots(觉醒技能槽, awakeningSlotCount, true);
        const secondRowHTML = `${awakeningRowHTML}${comboHTML}`;
        const comboMobileMainHTML = skillSystemMode === 'combo'
          ? `<div class="combo-main-core combo-main-core-mobile">${comboBaseHTML}</div>`
          : '';
        const comboGroupTriggerMobileHTML = skillSystemMode === 'combo'
          ? comboGroupTriggerHTML.replace('combo-group-trigger ', 'combo-group-trigger combo-group-trigger-mobile ')
          : '';
        const comboGroupTriggerDesktopHTML = skillSystemMode === 'combo'
          ? comboGroupTriggerHTML.replace('combo-group-trigger ', 'combo-group-trigger combo-group-trigger-desktop ')
          : '';
        const comboMobileAdvancedHTML = skillSystemMode === 'combo'
          ? `<div class="combo-mobile-advanced-grid">${comboGroupTriggerMobileHTML}<div class="combo-main-advanced-slots">${comboAdvancedHTML}</div></div>`
          : '';
        const comboMobileUtilityHTML = skillSystemMode === 'combo'
          ? `<div class="combo-mobile-utility-grid">${awakeningRowHTML}${comboHTML}</div>`
          : '';
        const comboMobileSecondaryHTML = skillSystemMode === 'combo'
          ? `${comboMobileAdvancedHTML}${comboMobileUtilityHTML}`
          : '';
        const comboDesktopSecondaryHTML = skillSystemMode === 'combo'
          ? `<div class="combo-desktop-advanced-group">
              <div class="combo-main-advanced combo-main-advanced-${comboStateKey} combo-main-advanced-row">
                ${comboGroupTriggerDesktopHTML}
                <div class="combo-main-advanced-slots">${comboAdvancedHTML}</div>
              </div>
            </div>
            <span class="combo-mobile-divider combo-desktop-divider" aria-hidden="true"></span>
            <div class="combo-desktop-utility-group">${awakeningRowHTML}${comboHTML}</div>`
          : '';
        const skillRowsHTML = skillSystemMode === 'combo'
          ? `<div class="slots-grid${comboMainGridClass} combo-layout-desktop"><div class="combo-main-core">${comboBaseHTML}</div></div>
            <div class="slots-grid combo-layout-desktop combo-secondary-grid" style="padding-bottom:10px">${comboDesktopSecondaryHTML}</div>
            <div class="combo-mobile-stack">
              <div class="slots-grid combo-mobile-main-grid">${comboMobileMainHTML}</div>
              <div class="slots-grid combo-mobile-secondary-grid" style="padding-bottom:10px">${comboMobileSecondaryHTML}</div>
            </div>`
          : `<div class="slots-grid classic-main-grid">${comboMainHTML}</div>
            <div class="slots-grid" style="padding-bottom:10px">${secondRowHTML}</div>`;

        // 召唤物栏渲染（技能槽下方，有才显示，遍历所有召唤物）
        const 召唤物 = 人物.召唤物 || {};
        let summonHTML = '';
        const summonEntries = Object.entries(召唤物);
        if (summonEntries.length > 0) {
          summonHTML = summonEntries.map(([key, s]) => {
            const sName = s.名称 || key;
            const hp = s.HP || 0, hpMax = s.HP上限 || 1;
            const hpPct = Math.max(0, Math.min(100, hp / hpMax * 100));
            const dur = s.持续时间 || '';
            const ac = s.AC;
            const skillRate = s.技能倍率 || '';
            const isCluster = sName.includes('|');
            const icon = isCluster ? 'ri-group-line' : 'ri-ghost-line';
            return `<div class="summon-bar">
              <div class="summon-bar-icon"><i class="${icon}"></i></div>
              <div class="summon-bar-info">
                <div class="summon-bar-name">${sName}</div>
                <div class="summon-bar-meta">
                  <div class="summon-bar-hp-track"><div class="summon-bar-hp-fill" style="width:${hpPct}%"></div></div>
                  <span class="summon-bar-hp-text">${hp}/${hpMax}</span>
                  ${ac != null ? `<span class="summon-bar-ac"><i class="ri-shield-line"></i> AC ${ac}</span>` : ''}
                  ${skillRate ? `<span class="summon-bar-rate"><i class="ri-flashlight-line"></i> ${skillRate}</span>` : ''}
                  ${dur ? `<span class="summon-bar-dur"><i class="ri-time-line"></i> ${dur}</span>` : ''}
                </div>
              </div>
            </div>`;
          }).join('');
        }

        // 资源技能渲染
        const 资源技能 = 人物.资源技能 || {};
        const resSkillEntries = Object.entries(资源技能);
        const resQualityColorMap = {
          '普通': { bg: 'rgba(45, 52, 54, 0.08)', color: '#636e72', border: 'rgba(45, 52, 54, 0.12)' },
          '精良': { bg: 'rgba(0, 71, 171, 0.08)', color: '#0047AB', border: 'rgba(0, 71, 171, 0.15)' },
          '稀有': { bg: 'rgba(155, 89, 182, 0.08)', color: '#9b59b6', border: 'rgba(155, 89, 182, 0.15)' },
          '卓越': { bg: 'rgba(232, 67, 147, 0.08)', color: '#e84393', border: 'rgba(232, 67, 147, 0.15)' },
          '传说': { bg: 'rgba(230, 126, 34, 0.08)', color: '#e67e22', border: 'rgba(230, 126, 34, 0.15)' },
          '史诗': { bg: 'rgba(201, 162, 39, 0.08)', color: '#C9A227', border: 'rgba(201, 162, 39, 0.15)' },
          '神话': { bg: 'rgba(232, 25, 139, 0.08)', color: '#e8198b', border: 'rgba(232, 25, 139, 0.15)' }
        };
        let resourceSkillsHTML = '';
        if (resSkillEntries.length > 0) {
          resourceSkillsHTML = '<div class="res-skill-list">';
          resSkillEntries.forEach(([skillName, skill]) => {
            const quality = normalizeQualityName(skill.品质 || '普通');
            const qStyle = resQualityColorMap[quality] || resQualityColorMap['普通'];
            const type = skill.类型 || '';
            const cost = normalizeSkillCost(skill.消耗);
            const left = skill.剩余次数 || 0;
            const max = skill.次数上限 || 0;
            const recover = skill.恢复条件 || '';
            const tags = skill.标签 || [];
            const effects = skill.效果 || {};
            const desc = skill.描述 || '';
            const ratio = max > 0 ? left / max : 0;
            const isLow = ratio <= 0.25 && left > 0;
            const effectEntries = Object.entries(effects).filter(([k]) => k !== '无');
            const tagsHTML = tags.map(t => `<span class="res-skill-tag-chip">${escapeHtml(t)}</span>`).join('');
            let effectHTML = '';
            if (effectEntries.length > 0) {
              effectHTML = '<div class="res-skill-effect-list">' + effectEntries.map(([k, v]) =>
                `<div class="res-skill-effect-item"><span class="label">${escapeHtml(k)}</span><span class="value">${escapeHtml(v)}</span></div>`
              ).join('') + '</div>';
            }

            // 决定显示方式：小槽（<=5次）或数字（>5次）
            let usesHTML = '';
            if (max <= 5 && max > 0) {
              // 使用小槽显示
              usesHTML = '<span class="res-skill-uses-label">次数</span><div class="res-skill-slots">';
              for (let i = 0; i < max; i++) {
                const isFilled = i < left;
                const slotClass = isFilled ? 'filled' : '';
                usesHTML += `<div class="res-skill-slot ${slotClass}"></div>`;
              }
              usesHTML += '</div>';
            } else {
              // 使用数字显示
              usesHTML = `<span class="res-skill-uses-label">次数</span>
                <span class="res-skill-uses-text">
                  <span class="current">${left}</span>
                  <span class="separator">/</span>
                  <span class="max">${max}</span>
                </span>`;
            }

            resourceSkillsHTML += `<div class="res-skill-card${left <= 0 ? ' exhausted' : ''}" data-res-skill="${escapeAttr(skillName)}">
              <i class="ri-arrow-down-s-line res-skill-chevron"></i>
              <div class="res-skill-card-header">
                <div class="res-skill-title">
                  <span class="res-skill-name${quality === '神话' ? ' myth-gradient-text' : ''}"${quality === '神话' ? '' : ` style="color:${qStyle.color}"`}>${escapeHtml(skillName)}</span>
                  <div class="res-skill-badges">
                    <span class="res-skill-quality" style="background:${qStyle.bg};color:${qStyle.color};border:1px solid ${qStyle.border}">${quality}</span>
                    ${type ? `<span class="res-skill-type-tag">${escapeHtml(type)}</span>` : ''}
                  </div>
                </div>
                <div class="res-skill-uses">
                  ${usesHTML}
                </div>
              </div>
              ${(cost || recover || tags.length > 0) ? `<div class="res-skill-meta">
                <span class="res-skill-recover"><i class="ri-fire-line"></i>${escapeHtml(`消耗 ${cost}`)}</span>
                ${recover ? `<span class="res-skill-recover"><i class="ri-loop-right-line"></i>${escapeHtml(recover)}</span>` : ''}
                ${tagsHTML}
              </div>` : ''}
              <div class="res-skill-detail">
                <div class="res-skill-detail-inner">
                  ${effectHTML}
                  ${desc ? `<div class="res-skill-desc">${escapeHtml(desc)}</div>` : ''}
                  <button class="res-skill-use-btn${left <= 0 ? ' disabled' : ''}" data-use-res-skill="${escapeAttr(skillName)}">
                    <i class="ri-play-circle-line"></i>使用技能
                  </button>
                </div>
              </div>
            </div>`;
          });
          resourceSkillsHTML += '</div>';
        } else {
          resourceSkillsHTML = '<div class="res-skill-empty"><i class="ri-flask-line"></i>暂无资源技能</div>';
        }

        // 熟练度渲染
        const profData = 人物.熟练度 || {};
        const profCombat = Object.entries(profData.战斗 || {});
        const profLife = Object.entries(profData.生活 || {});
        const profTotal = profCombat.length + profLife.length;
        const PROF_TIER_BONUS = { '学徒': 1, '熟手': 3, '专家': 4, '大师': 6, '传奇': 8 };
        const PROF_TIER_THRESHOLDS = { '学徒': 25, '熟手': 50, '专家': 100, '大师': 200, '传奇': 0 };
        const PROF_TIER_COLORS = { '学徒': '#636e72', '熟手': '#0984e3', '专家': '#6c5ce7', '大师': '#e17055', '传奇': '#d4af37' };

        function renderProfBlock(entries, category, title, iconClass) {
          if (entries.length === 0) return '';
          return `<div class="prof-block"><div class="prof-block-title"><i class="${iconClass}"></i>${title}</div>` +
            entries.map(([name, e]) => {
              const tier = e.阶位 || '学徒';
              const progress = parseInt(e.进度) || 0;
              const threshold = parseInt(e.升阶阈值) || (PROF_TIER_THRESHOLDS[tier] ?? 100);
              const pct = tier === '传奇' ? 100 : Math.min(100, Math.round(progress / Math.max(threshold, 1) * 100));
              const color = PROF_TIER_COLORS[tier] || '#636e72';
              const tierBg = `${color}15`;
              return `<div class="prof-item" style="--prof-color:${color}">
                <div class="prof-item-header">
                  <span class="prof-name">${name}</span>
                  <span class="prof-tier" style="color:${color};background:${tierBg}">${tier}<span class="prof-bonus">+${PROF_TIER_BONUS[tier] ?? 0}</span></span>
                  <button class="prof-forget-btn" data-prof-cat="${category}" data-prof-key="${name}" title="遗忘">遗忘</button>
                </div>
                <div class="prof-bar-bg"><div class="prof-bar-fill" style="width:${pct}%;background:${color}"></div></div>
                <div class="prof-progress-text">${tier === '传奇' ? 'MAX' : progress + '/' + threshold}</div>
              </div>`;
            }).join('') + '</div>';
        }

        let proficiencyHTML = '';
        if (profTotal > 0) {
          proficiencyHTML = '<div class="prof-list">' + renderProfBlock(profCombat, '战斗', '战斗', 'ri-sword-line') + renderProfBlock(profLife, '生活', '生活', 'ri-tools-line') + '</div>';
        } else {
          proficiencyHTML = '<div class="res-skill-empty"><i class="ri-bar-chart-line"></i>暂无熟练度</div>';
        }

        const nearbyEntries = Object.entries(附近的人);
        const hasNearby = nearbyEntries.length > 0;
        const nearbyContent = (() => {
          if (!hasNearby) {
            return '<div class="tab-placeholder"><i class="ri-map-pin-2-line"></i>暂无附近信息</div>';
          }
          let cardsHTML = '';
          nearbyEntries.forEach(([name, p]) => {
            const race = p.种族 || '未知';
            const gender = p.性别 || '';
            const lv = p.等级 || 1;
            const desc = p.外貌 || '';
            const shortName = name.length > 4 ? name.slice(0, 4) : name;
            cardsHTML += `<div class="nearby-card" data-nearby-name="${name.replace(/"/g, '&quot;')}">
              <div class="nearby-card-info">
                <div class="nearby-card-name">${name}</div>
                <div class="nearby-card-meta">
                  <span class="nearby-card-tag race">${race}</span>
                  ${gender ? `<span class="nearby-card-tag">${gender}</span>` : ''}
                  <span class="nearby-card-tag">Lv.${lv}</span>
                </div>
              </div>
              <div class="nearby-card-desc">
                ${desc ? `<span class="nearby-card-desc-text">${desc}</span>` : ''}
              </div>
              <div class="nearby-card-compact-name">${shortName}</div>
            </div>`;
          });
          const nearbyH = Math.min(460, (nearbyEntries.length + 1) * 82);
          return `<div class="nearby-section" id="nearby-container" style="height:${nearbyH}px">
            <div class="nearby-list-pane">${cardsHTML}</div>
            <div class="nearby-detail-pane" id="nearby-detail-container"></div>
          </div>`;
        })();

        const normalizeTextList = (items) => Array.from(new Set(
          (Array.isArray(items) ? items : [])
            .map(item => String(item || '').trim())
            .filter(Boolean)
        ));
        function normalizeSkillCost(value) {
          const text = String(value ?? '').trim();
          if (!text || text === 'undefined' || text === 'null') return '无';
          return text;
        }
        const renderMythicChipList = (items, extraClass = '') => {
          const normalized = normalizeTextList(items);
          if (normalized.length === 0) return '';
          return `<div class="mythic-chip-list">${normalized.map(item => `<span class="mythic-chip${extraClass ? ` ${extraClass}` : ''}">${escapeHtml(item)}</span>`).join('')}</div>`;
        };
        const renderMythicFoldSection = ({ title, icon, count, detailHTML }) => {
          return `<div class="bd-card mythic-fold-card" data-mythic-section="${escapeAttr(title)}" role="button" tabindex="0" aria-expanded="false">
            <i class="ri-arrow-down-s-line mythic-fold-chevron"></i>
            <div class="mythic-fold-head">
              <div class="bd-card-title"><i class="${icon}"></i> ${title}<span class="mythic-fold-count">${count}项</span></div>
            </div>
            <div class="mythic-fold-detail">
              <div class="mythic-fold-detail-inner">
                ${detailHTML}
              </div>
            </div>
          </div>`;
        };
        const renderMythicLayerSection = (title, icon, layerData) => {
          const entries = Object.entries(layerData || {});
          const detailHTML = entries.length > 0
            ? `<div class="mythic-layer-list">${entries.map(([itemName, itemData]) => {
              const sources = normalizeTextList(itemData?.溯源);
              const effect = typeof itemData?.效果 === 'string' ? itemData.效果.trim() : '';
              const sourceCountHTML = sources.length > 0
                ? `<span class="mythic-layer-count"><i class="ri-route-line"></i>${sources.length}条溯源</span>`
                : `<span class="mythic-layer-count empty"><i class="ri-route-line"></i>无溯源</span>`;
              const sourceListHTML = sources.length > 0
                ? renderMythicChipList(sources, 'muted')
                : '';
              return `<div class="mythic-layer-card">
                <div class="mythic-layer-head">
                  <span class="mythic-layer-name">${escapeHtml(itemName)}</span>
                </div>
                <div class="mythic-layer-meta-row">
                  ${sourceCountHTML}
                  ${sourceListHTML}
                </div>
                ${effect ? `<div class="mythic-layer-effect">${escapeHtml(effect)}</div>` : '<div class="mythic-empty">暂无效果说明</div>'}
              </div>`;
            }).join('')}</div>`
            : `<div class="mythic-empty">暂无${title}</div>`;
          return renderMythicFoldSection({
            title,
            icon,
            count: entries.length,
            detailHTML
          });
        };
        const 道途名称 = typeof 道途.道途名称 === 'string' ? 道途.道途名称.trim() : '';
        const 道途阶段 = Number.isFinite(Number(道途.阶段)) ? Math.max(0, Number(道途.阶段)) : 0;
        const 道途阶段称谓映射 = {
          1: '触火',
          2: '叩门',
          3: '见兆',
          4: '定相',
          5: '蜕形',
          6: '具名',
          7: '逾阶',
          8: '大功',
          9: '满溢',
          10: '登升'
        };
        const 道途阶段称谓 = 道途阶段称谓映射[道途阶段] || (道途阶段 > 0 ? `第${道途阶段}阶段` : '未定阶');
        const 道途阶位映射 = {
          1: '一阶',
          2: '二阶',
          3: '三阶',
          4: '四阶',
          5: '五阶',
          6: '六阶',
          7: '七阶',
          8: '八阶',
          9: '九阶',
          10: '十阶'
        };
        const 道途阶位文案 = 道途阶位映射[道途阶段] || (道途阶段 > 0 ? `${道途阶段}阶` : '未定阶');
