p: 18px;\n      padding-top: 16px;\n      border-top: 1px solid rgba(120, 145, 180, 0.12);\n    }\n\n    .detail-conn-item {\n      display: inline-flex;\n      align-items: center;\n      gap: 5px;\n      padding: 5px 12px;\n      margin: 3px 5px 3px 0;\n      border-radius: 999px;\n      font-size: 12.5px;\n      background: #eef3f9;\n      color: #3a6d99;\n      border: 1px solid #d3e0ee;\n      cursor: pointer;\n      transition: all 0.15s;\n    }\n\n    .detail-conn-item:hover {\n      background: #e2ecf7;\n      transform: translateY(-1px);\n    }\n\n    .detail-conn-dist {\n      font-size: 10px;\n      color: #7590ac;\n      margin-left: 2px;\n    }\n\n    /* ============ EDIT MODE STYLES ============ */\n    .edit-toolbar {\n      position: fixed;\n      top: 16px;\n      left: 16px;\n      z-index: 60;\n      display: flex;\n      gap: 6px;\n      align-items: center;\n    }\n\n    .edit-btn {\n      padding: 7px 15px;\n      border-radius: 9px;\n      font-size: 13px;\n      cursor: pointer;\n      font-family: 'Inter', 'Noto Sans SC', sans-serif;\n      font-weight: 600;\n      border: 1px solid rgba(120, 145, 180, 0.3);\n      background: rgba(255, 255, 255, 0.9);\n      color: #33465e;\n      transition: all 0.2s;\n      backdrop-filter: blur(6px);\n      box-shadow: 0 3px 10px -3px rgba(50, 80, 120, 0.28);\n    }\n\n    .edit-btn:hover {\n      background: #fff;\n    }\n\n    .edit-btn.active {\n      background: rgba(201, 137, 31, 0.16);\n      border-color: rgba(201, 137, 31, 0.55);\n      color: #a8690f;\n    }\n\n    .edit-btn.danger.active {\n      background: rgba(217, 70, 61, 0.14);\n      border-color: rgba(217, 70, 61, 0.55);\n      color: #c0342a;\n    }\n\n    .edit-btn.add.active {\n      background: rgba(47, 158, 92, 0.14);\n      border-color: rgba(47, 158, 92, 0.55);\n      color: #1f8050;\n    }\n\n    .edit-hint {\n      font-size: 11px;\n      color: #6a7a90;\n      margin-left: 8px;\n      font-family: 'Inter', 'Noto Sans SC', sans-