roke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"m3 10 13-7 13 7H3Zm3 4v11m7-11v11m6-11v11m7-11v11M3 29h26M3 25h26\"/></g></symbol><symbol id=\"icon-snow\" viewBox=\"0 0 32 32\"><g fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M16 2v28M4 9l24 14M4 23 28 9M12 5l4 4 4-4m-8 22 4-4 4 4M5 14l5-2-1-5m18 11-5 2 1 5M5 18l5 2-1 5m18-11-5-2 1-5\"/></g></symbol><symbol id=\"icon-scene\" viewBox=\"0 0 32 32\">\n        <circle cx=\"16\" cy=\"16\" r=\"8\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" />\n      </symbol>\n    </defs>\n  </svg>\n\n  <style>\nbody::before{display:none!important}.node-label{position:absolute;top:100%;left:50%;margin-top:8px;transform:translateX(-50%);pointer-events:none}#solaris-nav{position:fixed;top:57px;left:16px;right:16px;z-index:60;display:flex;gap:8px;flex-wrap:wrap;align-items:flex-start;pointer-events:none}#solaris-nav>*{pointer-events:auto}#solaris-nav select,#solaris-nav input,#solaris-nav button,.solaris-action{padding:9px 12px;border:1px solid #b7c7d9;background:#ffffffed;border-radius:9px;color:#30465f;font:13px 'Microsoft YaHei',sans-serif;box-shadow:0 3px 12px #56718d22}#solaris-search-box{position:relative;width:255px}#solaris-search{width:100%}#solaris-results{position:absolute;top:43px;left:0;right:0;max-height:300px;overflow:auto;background:white;border-radius:9px;box-shadow:0 7px 20px #45678944}#solaris-results button{display:block;width:100%;text-align:left;border-radius:0;border:0;box-shadow:none}#solaris-note{position:fixed;bottom:12px;left:50%;transform:translateX(-50%);padding:7px 12px;border-radius:8px;background:#ffffffd9;color:#66788a;font:11px 'Microsoft YaHei';z-index:40;max-width:48vw;text-align:center;pointer-events:none}.solaris-action{cursor:pointer;margin:8px 7px 4px 0;background:#edf5ff;color:#2867ac;border-color:#91b2d8}#solaris-loc{color:#168054;background:#fff;border-radius:8px;padding:8px;font:12px 'Microsoft YaHei'}@media(max-width:600px){#solaris-nav{left:9px;right:9px;gap:5px}#solaris-layers{max-width:100%;width:100%}#solaris-search-box{width:calc(100% - 77px)}#solaris-note{bottom:5px;max-width:70vw;font-size:9px}#legend{display:none}#map-title{max-width:95vw;overflow:hidden;text-overflow:ellipsis}#solaris-loc{display:none}#minimap{width:120px!important;height:90px!important}#zoom-controls{bottom:115px!important}}\n</style><div id=\"solaris-nav\"><select id=\"solaris-layers\" aria-label=\"地图分区\"></select><button id=\"solaris-back\" hidden>返回总图</button><div id=\"solaris-search-box\"><input id=\"solaris-search\" placeholder=\"搜索地点或内部地区\" aria-label=\"搜索地点\"><div id=\"solaris-results\"></div></div><button id=\"solaris-fit\">全览</button><span id=\"solaris-loc\"></span></div><!-- ============ MAP CONTAINER ============ -->\n  <div id=\"map-container\">\n    <canvas id=\"edge-canvas\"></canvas>\n    <div id=\"node-layer\"></div>\n  </div>\n\n  <!-- ============ TOOLTIP ============ -->\n  <div id=\"tooltip\" style=\"\n  display:none; position:fixed; z-index:100; pointer-events:none;\n  background:rgba(255,255,255,0.96); border:1px solid rgba(120,145,180,0.35);\n  border-radius:10px; padding:10px 13px; max-width:270px;\n  font-family:'Inter','Noto Sans SC',sans-serif; backdrop-filter:blur(8px);\n  box-shadow:0 8px 24px -6px rgba(40,65,105,0.4);\n\">\n    <div id=\"tt-name\" style=\"color:#22324a; font-size:14px; font-weight:700; margin-bottom:4px;\"></div>\n    <div id=\"tt-type\" style=\"color:#2f6bb0; font-size:11px; margin-bottom:5px; font-weight:600;\"></div>\n    <div id=\"tt-summary\" style=\"color:#55677e; font-size:12px; line-height:1.5; max-height:80px; overflow:hidden;\">\n    </div>\n  </div>\n\n  <!-- ============ DETAIL MODAL ============ -->\n  <div class=\"detail-overlay\" id=\"detail-overlay\">\n    <div class=\"detail-panel\" id=\"detail-panel\">\n      <button class=\"detail-close\" id=\"detail-close\" title=\"关闭\">&times;</button>\n      <div class=\"detail-header\" id=\"detail-header\"></div>\n      <div class=\"detail-summary\" id=\"detail-summary\"></div>\n      <div class=\"detail-body\" id=\"detail-body\"></div>\n    </div>\n  </div>\n\n  <!-- ============ TITLE ============ -->\n  <div id=\"map-title\" style=\"\n  position:fixed; top:14px; left:50%; transform:translateX(-50%); z-index:55;\n  font-family:'Inter','Noto Sans SC',sans-serif; font-size:14px; font-weight:800;\n  color:#26364c; letter-spacing:2px;\n  pointer-events:none; white-space:nowrap;\n  background: rgba(255,255,255,0.78); backdrop-filter:blur(8px);\n  padding: 7px 20px; border-radius: 999px; border: 1px solid rgba(120,145,180,0.25);\n  box-shadow: 0 4px 14px -4px rgba(50,80,120,0.28);\n\"></div>\n\n  <!-- ============ EDIT TOOLBAR ============ -->\n<div class=\"edit-toolbar\" id=\"edit-toolbar\" style=\"display:none;\">\n    <button class=\"edit-btn\" id=\"btn-edit-mode\" onclick=\"toggleEditMode()\">✏️ 编辑模式</button>\n    <button class=\"edit-btn add\" id=\"btn-add-edge\" onclick=\"toggleAddEdge()\" style=\"display:none;\">➕ 添加连线</button>\n    <button class=\"edit-btn danger\" id=\"btn-delete-edge\" onclick=\"toggleDeleteEdge()\" style=\"display:none;\">🗑️\n      删除连线</button>\n    <button class=\"edit-btn\" id=\"btn-export\" onclick=\"exportData()\" style=\"display:none;\">💾 导出数据</button>\n    <span class=\"edit-hint\" id=\"edit-hint\"></span>\n  </div>\n\n  <!-- ============ ZOOM CONTROLS ============ -->\n  <div id=\"zoom-controls\" style=\"\n  position:fixed; bottom:180px; right:16px; z-index:50;\n  display:flex; flex-direction:column; gap:6px;\n\">\n    <button onclick=\"zoomIn()\" style=\"\n    width:38px; height:38px; border:1px solid rgba(120,145,180,0.3);\n    background:rgba(255,255,255,0.9); color:#33465e; font-size:18px; font-weight:600;\n    border-radius:10px; cursor:pointer; font-family:'Inter',sans-serif;\n    box-shadow:0 3px 10px -3px rgba(50,80,120,0.3); backdrop-filter:blur(6px);\n  \">+</button>\n    <button onclick=\"zoomOut()\" style=\"\n    width:38px; height:38px; border:1px solid rgba(120,145,180,0.3);\n    background:rgba(255,255,255,0.9); color:#33465e; font-size:18px; font-weight:600;\n    border-radius:10px; cursor:pointer; font-family:'Inter',sans-serif;\n    box-shadow:0 3px 10px -3px rgba(50,80,120,0.3); backdrop-filter:blur(6px);\n  \">−</button>\n    <button onclick=\"resetView()\" title=\"定位到当前位置\" style=\"\n    width:38px; height:38px; border:1px solid rgba(120,145,180,0.3);\n    background:rgba(255,255,255,0.9); color:#2f9e5c; font-size:15px;\n    border-radius:10px; cursor:pointer; font-family:'Inter',sans-serif;\n    box-shadow:0 3px 10px -3px rgba(50,80,120,0.3); backdrop-filter:blur(6px);\n  \">⟲</button>\n  </div>\n\n  <!-- ============ MINIMAP ============ -->\n  <canvas id=\"minimap\" style=\"\n  position:fixed; bottom:16px; right:16px; z-index:50;\n  width:168px; height:128px; border:1px solid rgba(120,145,180,0.3);\n  border-radius:12px; background:rgba(255,255,255,0.9);\n  box-shadow:0 6px 18px -4px rgba(50,80,120,0.32); backdrop-filter:blur(6px);\n\"></canvas>\n\n  <!-- ============ LEGEND ============ -->\n  <div id=\"legend\" style=\"\n  position:fixed; bottom:16px; left:16px; z-index:50;\n  background:rgba(255,255,255,0.9); border:1px solid rgba(120,145,180,0.28);\n  border-radius:12px; padding:11px 14px; max-height:calc(100vh - 80px);\n  overflow-y:auto; backdrop-filter:blur(8px);\n  box-shadow:0 6px 18px -4px rgba(50,80,120,0.28);\n  font-family:'Inter','Noto Sans SC',sans-serif;\n\">\n    <div\n      style=\"color:#4a5c74; font-size:11px; font-weight:800; letter-spacing:2px; font-family:'Inter',sans-serif; cursor:pointer; display:flex; align-items:center; gap:7px; user-select:none;\"\n      onclick=\"var b=document.getElementById('legend-items');var a=document.getElementById('legend-arrow');if(b.style.display==='none'){b.style.display='grid';a.style.transform='rotate(0deg)';}else{b.style.display='none';a.style.transform='rotate(-90deg)';}\">\n      <span id=\"legend-arrow\"\n        style=\"display:inline-block;font-size:9px;transition:transform 0.2s;transform:rotate(-90deg);\">▼</span>\n      图例\n    </div>\n    <div id=\"legend-items\" style=\"display:none; grid-template-columns:1fr 1fr; gap:7px 16px; margin-top:10px;\"></div>\n  </div>\n\n  <!-- ============ DATA ============ -->\n\n\n  <script>\n    // ============ DATA CONFIG ============\n    const pageParams = new URLSearchParams(window.location.search);\n    const EMBED_BOOTSTRAP_CONFIG = window.__AMBER_MAP_EMBED_CONFIG__ || {};\n    const embedMode = String(EMBED_BOOTSTRAP_CONFIG.mode || '').trim();\n    const embedFlag = String(EMBED_BOOTSTRAP_CONFIG.embed || '').trim().toLowerCase();\n    const MAP_MODE = pageParams.get('mode') || embedMode || 'browse';\n    const IS_SPAWN_SELECT_MODE = MAP_MODE === 'spawn-select';\n    const IS_EMBED_MODE = pageParams.get('embed') === '1' || embedFlag === '1' || embedFlag === 'true';\n\n    // 与琥珀之剑、大明志异一致：由 head 中的同目录 script 直接提供 MAP_JSON_DATA。\n    // 当开局页把远程 HTML 注入 srcdoc 时，注入的 <base href> 会让相对路径仍指向远程同目录。\n    const LAYER_CONFIGS = [{\"cdnUrl\":\"\",\"localVar\":\"SOLARIS_LAYER_0\",\"label\":\"索拉里斯总图 · 今州 / 玄方 / 黎那汐塔 / 罗伊冰原\"},{\"cdnUrl\":\"\",\"localVar\":\"SOLARIS_LAYER_1\",\"label\":\"拉海洛 · 地下绿洲\"},{\"cdnUrl\":\"\",\"localVar\":\"SOLARIS_LAYER_2\",\"label\":\"阿维纽林\"},{\"cdnUrl\":\"\",\"localVar\":\"SOLARIS_LAYER_3\",\"label\":\"泰缇斯之底\"},{\"cdnUrl\":\"\",\"localVar\":\"SOLARIS_LAYER_4\",\"label\":\"黯原\"},{\"cdnUrl\":\"\",\"localVar\":\"SOLARIS_LAYER_5\",\"label\":\"梦枢天罗 · 万相神宫\"},{\"cdnUrl\":\"\",\"localVar\":\"SOLARIS_LAYER_6\",\"label\":\"隐海试验场 · 海底分图\"},{\"cdnUrl\":\"\",\"localVar\":\"SOLARIS_LAYER_7\",\"label\":\"下层金库 · 地下馆藏区\"}];\n\n    let currentLayerIndex = 0;\n    let layerDataCache = []; // 缓存已加载的层数据\n\n    async function loadLayerData(layerIdx) {\n      if (layerDataCache[layerIdx]) return layerDataCache[layerIdx];\n      const cfg = LAYER_CONFIGS[layerIdx];\n      // 1. 可选 CDN fetch（当前留空，与琥珀之剑实现保持一致）\n      if (cfg.cdnUrl) {\n        try {\n          const resp = await fetch(cfg.cdnUrl);\n          if (resp.ok) {\n            const text = await resp.text();\n            // JS 文件格式: var XXX = {...}; 提取 JSON 部分\n            const match = text.match(/=\\s*(\\{[\\s\\S]*\\})\\s*;?\\s*$/);\n            if (match) {\n              const json = JSON.parse(match[1]);\n              if (json && json.mapData) { layerDataCache[layerIdx] = json; return json; }\n            }\n          }\n        } catch (e) {\n          console.warn(`CDN 加载层${layerIdx + 1}失败:`, e.message);\n        }\n      }\n      // 2. 使用同目录 dragon_mapdata.js 已加载的全局变量\n      const localData = window[cfg.localVar];\n      if (localData && localData.mapData) { layerDataCache[layerIdx] = localData; return localData; }\n      return null;\n    }\n    // 层级背景主题\n    const LAYER_THEMES = [\n      'radial-gradient(80% 60% at 42% 42%, rgba(46,138,214,0.09) 0%, transparent 55%), radial-gradient(55% 45% at 74% 44%, rgba(124,92,208,0.08) 0%, transparent 55%), radial-gradient(50% 40% at 16% 34%, rgba(24,158,144,0.08) 0%, transparent 55%), radial-gradient(120% 100% at 50% 0%, #f5f7fa 0%, #e3e9f1 48%, #d4dde8 100%)',\n    ];\n\n    (async function init() {\n      const MAP_DATA = await loadLayerData(0);\n      if (!MAP_DATA) {\n        document.body.innerHTML = '<div style=\"color:#3c4c62;font-size:20px;text-align:center;margin-top:40vh;\">数据加载失败：请确保 dragon_mapdata.js 与地图文件位于同一目录</div>';\n        return;\n      }\n\n      let mapData = MAP_DATA.mapData;\n      let nodes = mapData.nodes;\n      let edges = mapData.edges || [];\n\n      // ============ SET TITLE ============\n      document.getElementById('map-title').textContent = mapData.title || '地理总图';\n\n      // ============ TYPE CONFIG ============\n      // ============ TYPE COLORS (light-modern semantic palette) ============\n      const TYPE_COLORS = {\n        city: '#2f7fd6', campus: '#7c5cd0', stronghold: '#c9891f', district: '#189e90',\n        facility: '#2f9e5c', nest: '#d9463d', zone: '#dd7a2b', otherspace: '#b23fce',\n        scene: '#6b7d94',\n        // legacy fantasy types kept for compatibility\n        castle: '#c9891f', temple: '#7c5cd0', port: '#2f7fd6', shop: '#dd7a2b',\n        dungeon: '#5a4a6a', tower: '#189e90', mine: '#8a6a3a', ruins: '#8a7a5a',\n        village: '#2f9e5c', town: '#189e90', camp: '#dd7a2b', waystation: '#6b7d94',\n        forest: '#2f9e5c', mountain: '#6b7d94', wilderness: '#8a7a5a', swamp: '#4a7a5a',\n        plains: '#7a9a4a', cemetery: '#6b7d94', desert: '#c9a04a', portal: '#b23fce',\n        ocean: '#2f7fd6', lake: '#189e90', faction: '#c9891f', tavern: '#dd7a2b',\n        poi: '#6b7d94',\n      };\n\n      const typeConfig = {\n        city: { size: 64, label: '大城市', labelSize: 20, bold: true },\n        district: { size: 50, label: '街区', labelSize: 17, bold: false },\n        campus: { size: 58, label: '学院', labelSize: 18, bold: true },\n        stronghold: { size: 60, label: '据点', labelSize: 18, bold: true },\n        facility: { size: 50, label: '设施', labelSize: 17, bold: false },\n        nest: { size: 54, label: '残象危险区', labelSize: 17, bold: false },\n        zone: { size: 50, label: '禁区', labelSize: 17, bold: false },\n        otherspace: { size: 54, label: '异空间', labelSize: 17, bold: false },\n        scene: { size: 34, label: '内部地点', labelSize: 16, bold: false },\n        castle: { size: 60, label: '城堡', labelSize: 19, bold: true },\n        temple: { size: 54, label: '神殿', labelSize: 18, bold: false },\n        port: { size: 50, label: '港口', labelSize: 17, bold: false },\n        shop: { size: 48, label: '商铺', labelSize: 17, bold: false },\n        dungeon: { size: 52, label: '地下城', labelSize: 18, bold: false },\n        tower: { size: 50, label: '塔楼', labelSize: 17, bold: false },\n        mine: { size: 48, label: '矿脉', labelSize: 17, bold: false },\n        ruins: { size: 50, label: '遗迹', labelSize: 17, bold: false },\n        village: { size: 46, label: '村庄', labelSize: 17, bold: false },\n        town: { size: 50, label: '城镇', labelSize: 17, bold: false },\n        camp: { size: 46, label: '营地', labelSize: 17, bold: false },\n        waystation: { size: 44, label: '驿站', labelSize: 16, bold: false },\n        forest: { size: 48, label: '森林', labelSize: 17, bold: false },\n        mountain: { size: 52, label: '山脉', labelSize: 17, bold: false },\n        wilderness: { size: 46, label: '荒野', labelSize: 17, bold: false },\n        swamp: { size: 46, label: '沼泽', labelSize: 17, bold: false },\n        plains: { size: 46, label: '平原', labelSize: 17, bold: false },\n        cemetery: { size: 46, label: '墓地', labelSize: 17, bold: false },\n        desert: { size: 48, label: '荒漠', labelSize: 17, bold: false },\n        portal: { size: 50, label: '传送门', labelSize: 17, bold: false },\n        ocean: { size: 50, label: '海洋', labelSize: 17, bold: false },\n        lake: { size: 46, label: '湖泊', labelSize: 17, bold: false },\n        faction: { size: 48, label: '势力', labelSize: 17, bold: false },\n        tavern: { size: 46, label: '酒馆', labelSize: 17, bold: false },\n        poi: { size: 46, label: '兴趣点', labelSize: 17, bold: false },\n      };\n\n      // ============ FIELD LABELS (English key -> Chinese label) ============\n      Object.assign(TYPE_COLORS,{\"island\":\"#528c66\",\"archipelago\":\"#586d68\",\"mountainisland\":\"#63878a\",\"skytemple\":\"#7963bd\",\"library\":\"#8a62b7\",\"workshop\":\"#ac782c\",\"medical\":\"#d06d7e\",\"laboratory\":\"#448ca8\",\"spaceship\":\"#6277c5\",\"garden\":\"#52966a\",\"windmill\":\"#5e91ad\",\"bridge\":\"#6f8d9d\",\"gate\":\"#9a803d\",\"energy\":\"#c28d2e\",\"tree\":\"#4a986f\",\"waterfall\":\"#418faf\",\"labyrinth\":\"#9164b9\",\"flame\":\"#cf7751\",\"sun\":\"#c28d2e\",\"moon\":\"#7676b6\",\"rain\":\"#608eac\",\"mirror\":\"#a26eae\",\"anchor\":\"#667e9d\",\"swords\":\"#9a7853\",\"bank\":\"#bc9740\",\"snow\":\"#69a2b9\"});\nObject.assign(typeConfig,{\"island\":{\"size\":50,\"label\":\"岛屿陆地\",\"labelSize\":17,\"bold\":false},\"archipelago\":{\"size\":50,\"label\":\"群岛\",\"labelSize\":17,\"bold\":false},\"mountainisland\":{\"size\":50,\"label\":\"山地岛屿\",\"labelSize\":17,\"bold\":false},\"skytemple\":{\"size\":60,\"label\":\"空中神殿\",\"labelSize\":17,\"bold\":true},\"library\":{\"size\":50,\"label\":\"书馆\",\"labelSize\":17,\"bold\":false},\"workshop\":{\"size\":50,\"label\":\"工坊\",\"labelSize\":17,\"bold\":false},\"medical\":{\"size\":50,\"label\":\"医护\",\"labelSize\":17,\"bold\":false},\"laboratory\":{\"size\":50,\"label\":\"研究观测\",\"labelSize\":17,\"bold\":false},\"spaceship\":{\"size\":50,\"label\":\"空间站\",\"labelSize\":17,\"bold\":false},\"garden\":{\"size\":50,\"label\":\"庭园\",\"labelSize\":17,\"bold\":false},\"windmill\":{\"size\":50,\"label\":\"风车\",\"labelSize\":17,\"bold\":false},\"bridge\":{\"size\":50,\"label\":\"廊桥渡口\",\"labelSize\":17,\"bold\":false},\"gate\":{\"size\":50,\"label\":\"关门\",\"labelSize\":17,\"bold\":false},\"energy\":{\"size\":50,\"label\":\"能源\",\"labelSize\":17,\"bold\":false},\"tree\":{\"size\":50,\"label\":\"古树\",\"labelSize\":17,\"bold\":false},\"waterfall\":{\"size\":50,\"label\":\"瀑布水流\",\"labelSize\":17,\"bold\":false},\"labyrinth\":{\"size\":50,\"label\":\"迷宫\",\"labelSize\":17,\"bold\":false},\"flame\":{\"size\":50,\"label\":\"余烬\",\"labelSize\":17,\"bold\":false},\"sun\":{\"size\":50,\"label\":\"暖光\",\"labelSize\":17,\"bold\":false},\"moon\":{\"size\":50,\"label\":\"沉静\",\"labelSize\":17,\"bold\":false},\"rain\":{\"size\":50,\"label\":\"冷雨\",\"labelSize\":17,\"bold\":false},\"mirror\":{\"size\":50,\"label\":\"心相\",\"labelSize\":17,\"bold\":false},\"anchor\":{\"size\":50,\"label\":\"锚定构造\",\"labelSize\":17,\"bold\":false},\"swords\":{\"size\":50,\"label\":\"剑授战备\",\"labelSize\":17,\"bold\":false},\"bank\":{\"size\":50,\"label\":\"金库金融\",\"labelSize\":17,\"bold\":false},\"snow\":{\"size\":50,\"label\":\"冰雪\",\"labelSize\":17,\"bold\":false}});\nconst FIELD_LABELS = {\n        originalReference: '原始参考',\n        tier: '层级区域',\n        nature: '地点性质',\n        newLandscape: '地貌描述',\n        monsters: '怪物',\n        residentFactions: '驻留势力',\n        populationComposition: '人口构成',\n        security: '治安',\n        economy: '经济',\n        NPC: 'NPC',\n        keyNPCs: '关键NPC',\n        npcAndFunction: 'NPC与功能',\n        function: '功能',\n        specialFunction: '特殊功能',\n        environmentFeatures: '环境特征',\n        environmentalHazards: '环境危害',\n        dangerLevel: '危险等级',\n        ecology: '生态',\n        danger: '危险',\n        operation: '运营',\n        militaryPower: '军事力量',\n        politicalStance: '政治立场',\n        apostleProjection: '使徒投影',\n        clearSignificance: '通关意义',\n        special: '特殊',\n        settlement: '聚落',\n        settlementFunction: '聚落功能',\n        ecologicalChain: '生态链',\n        civilizationImpact: '文明影响',\n        relationWithSixteenRaces: '与十六种族关系',\n        fullName: '完整名称',\n        region: '地理区域',\n        bloodIndex: '龙血指数',\n        people: '人群',\n        dailyLife: '日常',\n        peopleDaily: '人群生态与日常生活',\n        shadow: '里世界',\n        shadowPattern: '里侧格局',\n        factions: '相关势力',\n        dragonTrace: '龙类痕迹',\n        resources: '资源',\n        access: '交通与进入',\n        resourcesAccess: '资源与入口',\n        threats: '威胁与麻烦',\n        scenes: '子场景',\n        canon: '原著锚点',\n        hooks: '剧情钩子',\n        legends: '传说与流言',\n        parentName: '所属地点',\n      };\n\n      const PHYSICAL_LABELS = {\n        terrain: '地形',\n        lighting: '光照',\n        gravity: '重力',\n        temperaturePressure: '温度与气压',\n        hydrology: '水文',\n      };\n\n      // Fields to skip in detail modal\n      Object.assign(FIELD_LABELS,{地点资料:'地点资料',资料状态:'资料状态',定位说明:'定位说明',改编说明:'改编说明',资料来源:'资料来源',地图说明:'地图说明'});\n      const SKIP_FIELDS = new Set([\n        'id', 'name', 'type', 'x', 'y', 'discovered', 'secrets', 'detailMap',\n        'brief', 'summary', 'physicalConsequences', 'encounters', 'loot',\n        'lon', 'lat', 'independent', 'geoNote', 'displayName', 'parentId'\n      ]);\n      const NODE_FIELD_PRIORITY = ['id', 'name', 'type', 'x', 'y', 'region', 'tier', 'dangerLevel', 'bloodIndex', 'newLandscape', 'peopleDaily', 'shadowPattern', 'dragonTrace', 'resourcesAccess', 'threats', 'legends', 'scenes'];\n\n      function getOrderedNodeEntries(obj) {\n        const order = new Map(NODE_FIELD_PRIORITY.map((key, index) => [key, index]));\n        return Object.entries(obj)\n          .map(([key, value], index) => ({\n            key,\n            value,\n            index,\n            priority: order.has(key) ? order.get(key) : Number.MAX_SAFE_INTEGER\n          }))\n          .sort((a, b) => {\n            if (a.priority !== b.priority) return a.priority - b.priority;\n            return a.index - b.index;\n          })\n          .map(({ key, value }) => [key, value]);\n      }\n\n      // ============ STATE ============\n      const SPREAD = 2.0;\n      const SCENE_VISIBLE_SCALE = 0.4;\n      const SCENE_LABEL_VISIBLE_SCALE = 0.4;\n      let viewX = 0, viewY = 0, scale = 0.65;\n      let isDragging = false, dragStartX = 0, dragStartY = 0, dragViewX = 0, dragViewY = 0;\n      let clickStartX = 0, clickStartY = 0;\n      let nodeMap = {};\n      nodes.forEach(n => { nodeMap[n.id] = n; });\n\n      // Edit mode state\n      let editMode = false;\n      let deleteEdgeMode = false;\n      let addEdgeMode = false;\n      let edgeAddSourceId = null;\n      let nodeDragging = null;\n      let nodeDragStartX = 0, nodeDragStartY = 0;\n      let nodeOrigX = 0, nodeOrigY = 0;\n      let deletedEdges = []; // track deleted edges for undo\n      // ============ DOM REFS ============\n      const container = document.getElementById('map-container');\n      const canvas = document.getElementById('edge-canvas');\n      const ctx = canvas.getContext('2d');\n      const nodeLayer = document.getElementById('node-layer');\n      const tooltip = document.getElementById('tooltip');\n      const minimap = document.getElementById('minimap');\n      const minimapCtx = minimap.getContext('2d');\n      const detailOverlay = document.getElementById('detail-overlay');\n      const detailPanel = document.getElementById('detail-panel');\n      const detailHeader = document.getElementById('detail-header');\n      const detailSummary = document.getElementById('detail-summary');\n      const detailBody = document.getElementById('detail-body');\n      const detailClose = document.getElementById('detail-close');\n      const WORLD_NAME = '龙族世界';\n\n      function getLayerDisplayName(layerIdx = currentLayerIndex) {\n        return WORLD_NAME;\n      }\n\n      function updateSpawnSelectBanner(selectedName = '') {\n        return;\n      }\n\n      // 仅特异空间及奥丁之渊不可作为出生点；普通龙巢、禁区、隔离区和现实场景均可选择。\n      const BLOCKED_SPAWN_IDS = new Set([\n        'otherspace_rain_train',\n        'otherspace_tokoyo',\n        'otherspace_nibelungen',\n        'otherspace_dreamcorridor',\n        'otherspace_thriller_paradise',\n        'nest_odin'\n      ]);\n\n      function getSpawnBlockedReason(node) {\n        if (!node) return '';\n        const nodeId = String(node.id || '').trim();\n        const parentId = String(node.parentId || '').trim();\n        const blockedId = BLOCKED_SPAWN_IDS.has(nodeId) ? nodeId : (BLOCKED_SPAWN_IDS.has(parentId) ? parentId : '');\n        if (!blockedId) return '';\n        if (blockedId === 'nest_odin') return '奥丁之渊无法作为初始出生点。';\n        return '该地点属于特异空间，无法作为初始出生点。';\n      }\n\n      function showSpawnBlockedMessage(node) {\n        const reason = getSpawnBlockedReason(node) || '该地点不可选为出生点。';\n        window.alert(reason);\n      }\n      function buildSpawnSelectionPayload(node) {\n        return {\n          名称: node.name==='今州'?'今州城':node.name || '',\n          大陆: '索拉里斯',\n          区域: mapData.title.replace('索拉里斯 · ','') || '',\n          场所: node.name || '',\n          层级: node.tier || '',\n          地区等级: node.dangerLevel || '',\n          危险等级: node.dangerLevel || '',\n          地貌特征: node.newLandscape || node.physicalConsequences?.terrain || node.summary || '',\n          聚落描述: node.peopleDaily || node.brief || node.summary || '',\n          周边威胁: node.monsters || node.environmentalHazards || node.danger || '',\n          地点类型: (typeConfig[node.type] || typeConfig.poi || {}).label || '',\n          节点ID: node.id || '',\n          地图层级: currentLayerIndex\n        };\n      }\n\n      const SPAWN_CHANNEL = 'dragon-spawn-map';\n\n      function emitSpawnSelection(node) {\n        const payload = buildSpawnSelectionPayload(node);\n        if (!payload.名称) return;\n        const reason = getSpawnBlockedReason(node);\n        try {\n          if (reason) {\n            window.parent?.postMessage({ channel: SPAWN_CHANNEL, type: 'dragon_spawn_blocked', spawn: payload, reason }, '*');\n            // 嵌入开局页时由父页面统一弹窗，避免同一次选择出现两遍提示。\n            if (window.parent === window) showSpawnBlockedMessage(node);\n          } else {\n            updateSpawnSelectBanner(payload.名称);\n            window.parent?.postMessage({ channel: SPAWN_CHANNEL, type: 'solaris_spawn_selected', spawn: payload }, '*');\n          }\n        } catch (e) {}\n      }\n\n      if (IS_SPAWN_SELECT_MODE) updateSpawnSelectBanner('');\n\n      // ============ COORDINATE HELPERS ============\n      function worldToScreen(wx, wy) {\n        const cx = window.innerWidth / 2;\n        const cy = window.innerHeight / 2;\n        return {\n          x: cx + (wx * SPREAD + viewX) * scale,\n          y: cy + (wy * SPREAD + viewY) * scale\n        };\n      }\n\n      function buildEdgePath(edge, src, tgt) {\n        const s = worldToScreen(src.x, src.y);\n        const t = worldToScreen(tgt.x, tgt.y);\n        const curve = Number(edge.curve || 0);\n        if (!Number.isFinite(curve) || Math.abs(curve) < 0.001) {\n          return { s, t, c: null, curved: false };\n        }\n\n        const dx = t.x - s.x;\n        const dy = t.y - s.y;\n        const len = Math.hypot(dx, dy) || 1;\n        return {\n          s,\n          t,\n          curved: true,\n          c: {\n            x: (s.x + t.x) / 2 + (-dy / len) * len * curve,\n            y: (s.y + t.y) / 2 + (dx / len) * len * curve,\n          }\n        };\n      }\n\n      function edgePathPoint(path, u = 0.5) {\n        if (!path.curved || !path.c) {\n          return {\n            x: path.s.x + (path.t.x - path.s.x) * u,\n            y: path.s.y + (path.t.y - path.s.y) * u,\n          };\n        }\n        const a = (1 - u) * (1 - u);\n        const b = 2 * (1 - u) * u;\n        const c = u * u;\n        return {\n          x: a * path.s.x + b * path.c.x + c * path.t.x,\n          y: a * path.s.y + b * path.c.y + c * path.t.y,\n        };\n      }\n\n      function edgePathTangent(path, u = 0.5) {\n        if (!path.curved || !path.c) {\n          return { x: path.t.x - path.s.x, y: path.t.y - path.s.y };\n        }\n        return {\n          x: 2 * (1 - u) * (path.c.x - path.s.x) + 2 * u * (path.t.x - path.c.x),\n          y: 2 * (1 - u) * (path.c.y - path.s.y) + 2 * u * (path.t.y - path.c.y),\n        };\n      }\n\n      // ============ RESIZE ============\n      function resizeCanvas() {\n        const dpr = devicePixelRatio || 1;\n        canvas.width = window.innerWidth * dpr;\n        canvas.height = window.innerHeight * dpr;\n        canvas.style.width = window.innerWidth + 'px';\n        canvas.style.height = window.innerHeight + 'px';\n        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n        minimap.width = 168 * dpr;\n        minimap.height = 128 * dpr;\n        render();\n      }\n      window.addEventListener('resize', resizeCanvas);\n\n      // ============ RENDER EDGES ============\n      function renderEdges() {\n        ctx.clearRect(0, 0, window.innerWidth, window.innerHeight);\n\n        ctx.save();\n        ctx.lineCap = 'round';\n\n        function getEdgeStyle(edge) {\n          if (edge.type === 'special') {\n            return {\n              strokeStyle: edge.curve ? 'rgba(178,63,206,0.55)' : 'rgba(178,63,206,0.5)',\n              lineWidth: edge.curve ? 1.7 : 2.0,\n              dash: edge.curve ? [3, 8] : [4, 6],\n              labelColor: '#9a2fbf',\n              labelBackground: 'rgba(255,255,255,0.9)',\n              labelBorder: 'rgba(178,63,206,0.35)'\n            };\n          }\n          if (edge.type === 'gateway') {\n            return {\n              strokeStyle: edge.curve ? 'rgba(47,127,214,0.5)' : 'rgba(178,63,206,0.42)',\n              lineWidth: edge.curve ? 1.6 : 1.8,\n              dash: edge.curve ? [2, 8] : [2, 8],\n              labelColor: edge.curve ? '#2f6bb0' : '#9a2fbf',\n              labelBackground: 'rgba(255,255,255,0.9)',\n              labelBorder: edge.curve ? 'rgba(47,127,214,0.3)' : 'rgba(178,63,206,0.3)'\n            };\n          }\n          if (edge.type === 'scene') {\n            return {\n              strokeStyle: 'rgba(120,140,170,0.42)',\n              lineWidth: 1.1,\n              dash: [2, 6],\n              labelColor: '#7186a0',\n              labelBackground: 'rgba(255,255,255,0.85)',\n              labelBorder: 'rgba(120,145,180,0.28)'\n            };\n          }\n          if (edge.type === 'route') {\n            // cross-region proximity link — a touch stronger than local roads\n            return {\n              strokeStyle: 'rgba(90,120,158,0.5)',\n              lineWidth: 1.5,\n              dash: [7, 6],\n              labelColor: '#3c4c62',\n              labelBackground: 'rgba(255,255,255,0.9)',\n              labelBorder: 'rgba(120,145,180,0.28)'\n            };\n          }\n          // default local road (type 'road' / 'regional-mst' / legacy)\n          return {\n            strokeStyle: 'rgba(96,120,150,0.42)',\n            lineWidth: 1.35,\n            dash: [6, 7],\n            labelColor: '#4a5c74',\n            labelBackground: 'rgba(255,255,255,0.9)',\n            labelBorder: 'rgba(120,145,180,0.28)'\n          };\n        }\n\n        edges.forEach(e => {\n          if (e.type === 'scene' && scale < SCENE_VISIBLE_SCALE) return;\n          const src = nodeMap[e.source];\n          const tgt = nodeMap[e.target];\n          if (!src || !tgt) return;\n          if (scale < SCENE_VISIBLE_SCALE && (src.type === 'scene' || tgt.type === 'scene')) return;\n          const style = getEdgeStyle(e);\n          ctx.strokeStyle = style.strokeStyle;\n          ctx.lineWidth = style.lineWidth * Math.max(0.6, scale);\n          ctx.setLineDash(style.dash.map(v => v * Math.max(0.7, scale)));\n          const path = buildEdgePath(e, src, tgt);\n          ctx.beginPath();\n          ctx.moveTo(path.s.x, path.s.y);\n          if (path.curved) ctx.quadraticCurveTo(path.c.x, path.c.y, path.t.x, path.t.y);\n          else ctx.lineTo(path.t.x, path.t.y);\n          ctx.stroke();\n        });\n        ctx.restore();\n\n        // Edge labels — avoid overlapping with node positions\n        ctx.save();\n        const labelFontSize = Math.max(10, Math.min(15, 11 * scale));\n        ctx.font = `500 ${labelFontSize}px 'Noto Serif SC', serif`;\n        ctx.textAlign = 'center';\n        ctx.textBaseline = 'middle';\n\n        // Collect node screen rects for collision detection\n        function textVisualUnits(text) {\n          return [...String(text || '')].reduce((sum, ch) => sum + (/[\\x00-\\x7F]/.test(ch) ? 0.55 : 1), 0);\n        }\n\n        const nodeRects = [];\n        nodes.forEach(n => {\n          if (n.type === 'scene' && scale < SCENE_VISIBLE_SCALE) return;\n          const p = worldToScreen(n.x, n.y);\n          const cfg = typeConfig[n.type] || typeConfig.poi;\n          const nodeScale = Math.min(1.2, Math.max(0.5, scale));\n          const labelWidth = textVisualUnits(n.name) * cfg.labelSize + (n.type === 'scene' ? 16 : 24);\n          const hw = (Math.max(cfg.size, labelWidth) * 0.5 + 12) * nodeScale;\n          const hh = (cfg.size * 0.5 + cfg.labelSize * 0.85 + 18) * nodeScale;\n          nodeRects.push({ x: p.x - hw, y: p.y - hh, w: hw * 2, h: hh * 2 });\n        });\n\n        function rectsOverlap(ax, ay, aw, ah, bx, by, bw, bh) {\n          return ax < bx + bw && ax + aw > bx && ay < by + bh && ay + ah > by;\n        }\n\n        edges.forEach(e => {\n          if (e.type === 'scene' && scale < SCENE_VISIBLE_SCALE) return;\n          const src = nodeMap[e.source];\n          const tgt = nodeMap[e.target];\n          if (!src || !tgt) return;\n          if (scale < SCENE_VISIBLE_SCALE && (src.type === 'scene' || tgt.type === 'scene')) return;\n          const style = getEdgeStyle(e);\n          const path = buildEdgePath(e, src, tgt);\n          const mid = edgePathPoint(path, 0.5);\n          let mx = mid.x;\n          let my = mid.y;\n          if (scale < 0.92) return;\n          const text = e.label || '';\n          if (!text) return;\n          const tw = ctx.measureText(text).width;\n          const ph = Math.max(16, labelFontSize + 8);\n          const pw = tw + 16;\n\n          // Check overlap with any node and nudge if needed\n          const tangent = edgePathTangent(path, 0.5);\n          const dx = tangent.x;\n          const dy = tangent.y;\n          const len = Math.sqrt(dx * dx + dy * dy) || 1;\n          // Perpendicular direction\n          const nx = -dy / len;\n          const ny = dx / len;\n          const nudgeStep = 18;\n          let blocked = false;\n          for (let attempt = 0; attempt < 6; attempt++) {\n            let overlaps = false;\n            for (const nr of nodeRects) {\n              if (rectsOverlap(mx - pw / 2, my - ph / 2, pw, ph, nr.x, nr.y, nr.w, nr.h)) {\n                overlaps = true;\n                break;\n              }\n            }\n            if (!overlaps) break;\n            // Alternate nudge direction: perpendicular, then along edge\n            if (attempt % 2 === 0) {\n              mx += nx * nudgeStep;\n              my += ny * nudgeStep;\n            } else {\n              mx -= nx * nudgeStep * 2;\n              my -= ny * nudgeStep * 2;\n            }\n            blocked = attempt === 5;\n          }\n          if (blocked) return;\n\n          ctx.fillStyle = style.labelBackground || 'rgba(12,18,28,0.78)';\n          ctx.beginPath();\n          ctx.roundRect(mx - pw / 2, my - ph / 2, pw, ph, 4);\n          ctx.fill();\n          ctx.strokeStyle = style.labelBorder || 'rgba(138,122,90,0.2)';\n          ctx.lineWidth = 0.6;\n          ctx.setLineDash([]);\n          ctx.stroke();\n          ctx.fillStyle = style.labelColor || '#c8b890';\n          ctx.fillText(text, mx, my);\n        });\n        ctx.restore();\n      }\n\n      // ============ RENDER NODES ============\n      let nodeElements = [];\n      function createNodeElements() {\n        nodeLayer.innerHTML = '';\n        nodeElements = [];\n        nodes.forEach(n => {\n          const cfg = typeConfig[n.type] || typeConfig.poi;\n          const wrapper = document.createElement('div');\n          wrapper.className = 'node-wrapper';\n          wrapper.dataset.id = n.id;\n          wrapper.dataset.type = n.type;wrapper.dataset.icon = n.iconType || n.type;\n          wrapper.style.setProperty('--nc', TYPE_COLORS[n.iconType || n.type] || TYPE_COLORS.poi);\n          if (['city', 'castle', 'campus', 'stronghold'].includes(n.type)) wrapper.dataset.tier = 'major';\n\n          const iconSize = cfg.size;\n          const iconDiv = document.createElement('div');\n          iconDiv.className = 'node-icon';\n          if (n.type === 'otherspace') {\n            // ornate icon fills the whole footprint, no disc\n            iconDiv.innerHTML = `<svg width=\"${iconSize}\" height=\"${iconSize}\" viewBox=\"0 0 32 32\"><use href=\"#icon-${n.iconType || n.type}\"/></svg>`;\n          } else {\n            iconDiv.style.width = iconSize + 'px';\n            iconDiv.style.height = iconSize + 'px';\n            const glyph = Math.round(iconSize * (n.type === 'scene' ? 0.77 : 0.66));\n            iconDiv.innerHTML = `<svg width=\"${glyph}\" height=\"${glyph}\" viewBox=\"0 0 32 32\"><use href=\"#icon-${n.iconType || n.type}\"/></svg>`;\n          }\n\n          const label = document.createElement('div');\n          label.className = 'node-label';\n          label.style.fontSize = cfg.labelSize + 'px';\n          if (n.type === 'scene') {\n            label.style.padding = '1px 7px';\n            label.style.background = 'rgba(255,255,255,0.82)';\n            label.style.color = '#55637a';\n            label.style.fontWeight = '500';\n          }\n          if (cfg.bold) label.style.fontWeight = '600';\n          label.textContent = n.name;\n\n          wrapper.appendChild(iconDiv);\n          wrapper.appendChild(label);\n\n          // ============ SPECIAL MARKERS ============\n          if (IS_SPAWN_SELECT_MODE && n.id === 'city_hometown') {\n            const markerBg = document.createElement('div');\n            markerBg.className = 'special-marker-recommended';\n            markerBg.style.cssText = 'width:100%;height:100%;position:absolute;top:0;left:0;';\n            wrapper.insertBefore(markerBg, iconDiv);\n            const badge = document.createElement('div');\n            badge.className = 'special-badge-recommended';\n            badge.textContent = '推荐出生点';\n            wrapper.appendChild(badge);\n          }\n          if (n.independent) {\n            const markerBg = document.createElement('div');\n            markerBg.className = 'special-marker-layer3';\n            markerBg.style.cssText = 'width:100%;height:100%;position:absolute;top:0;left:0;';\n            wrapper.insertBefore(markerBg, iconDiv);\n            const badge = document.createElement('div');\n            badge.className = 'special-badge-layer3';\n            badge.textContent = '◇ 独立异空间';\n            wrapper.appendChild(badge);\n          }\n\n          if (n.id === 'otherspace_thriller_paradise') {\n            const markerBg = document.createElement('div');\n            markerBg.className = 'special-marker-worldscar';\n            markerBg.style.cssText = 'width:100%;height:100%;position:absolute;top:0;left:0;';\n            wrapper.insertBefore(markerBg, iconDiv);\n            const badge = document.createElement('div');\n            badge.className = 'special-badge-worldscar';\n            badge.textContent = '◆ 来吧，参与这超越思维的游戏';\n            wrapper.appendChild(badge);\n          }\n\n          // Tooltip events\n          wrapper.addEventListener('mouseenter', () => {\n            tooltip.style.display = 'block';\n            document.getElementById('tt-name').textContent = n.fullName || n.name;\n            document.getElementById('tt-type').textContent = cfg.label;\n            document.getElementById('tt-summary').textContent = (n.brief || n.summary || '').replace(/\\n/g, ' ').substring(0, 140);\n          });\n          wrapper.addEventListener('mousemove', (ev) => {\n            tooltip.style.left = (ev.clientX + 14) + 'px';\n            tooltip.style.top = (ev.clientY + 14) + 'px';\n            const tr = tooltip.getBoundingClientRect();\n            if (tr.right > window.innerWidth - 8) tooltip.style.left = (ev.clientX - tr.width - 10) + 'px';\n            if (tr.bottom > window.innerHeight - 8) tooltip.style.top = (ev.clientY - tr.height - 10) + 'px';\n          });\n          wrapper.addEventListener('mouseleave', () => {\n            tooltip.style.display = 'none';\n          });\n\n          // Click to open detail OR drag node in edit mode\n          wrapper.addEventListener('mousedown', (ev) => {\n            clickStartX = ev.clientX;\n            clickStartY = ev.clientY;\n            if (editMode) {\n              ev.stopPropagation();\n              if (addEdgeMode) return;\n              nodeDragging = n;\n              nodeDragStartX = ev.clientX;\n              nodeDragStartY = ev.clientY;\n              nodeOrigX = n.x;\n              nodeOrigY = n.y;\n            }\n          });\n          wrapper.addEventListener('mouseup', (ev) => {\n            const dx = Math.abs(ev.clientX - clickStartX);\n            const dy = Math.abs(ev.clientY - clickStartY);\n\n            if (editMode && addEdgeMode) {\n              if (dx < 5 && dy < 5) {\n                tooltip.style.display = 'none';\n                handleEdgeAddNodeClick(n);\n              }\n              return;\n            }\n\n            if (nodeDragging === n) {\n              nodeDragging = null;\n              if (dx < 5 && dy < 5) return; // was just a click, no drag\n              return; // finished dragging\n            }\n            if (dx < 5 && dy < 5 && !editMode) {\n              tooltip.style.display = 'none';\n              if (IS_SPAWN_SELECT_MODE) emitSpawnSelection(n);\n              else openDetail(n);\n            }\n          });\n\n          wrapper.classList.toggle('editing', editMode);\n          wrapper.classList.toggle('edge-source', addEdgeMode && edgeAddSourceId === n.id);\n          nodeLayer.appendChild(wrapper);\n          nodeElements.push({ el: wrapper, node: n });\n        });\n      }\n\n      function updateNodePositions() {\n        nodeElements.forEach(({ el, node }) => {\n          if (node.type === 'scene' && scale < SCENE_VISIBLE_SCALE) {\n            el.style.display = 'none';\n            return;\n          }\n          el.style.display = '';\n          const pos = worldToScreen(node.x, node.y);\n          el.style.left = pos.x + 'px';\n          el.style.top = pos.y + 'px';\n          el.style.transform = `translate(-50%,-50%) scale(${Math.min(1.2, Math.max(0.5, scale))})`;\n          const lbl = el.querySelector('.node-label');\n          if (lbl) {\n            if (node.type === 'scene') {\n              lbl.style.opacity = scale < SCENE_LABEL_VISIBLE_SCALE ? '0' : scale < 1.25 ? '0.72' : '0.92';\n            } else {\n              lbl.style.opacity = scale < 0.35 ? '0' : scale < 0.55 ? '0.6' : '1';\n            }\n          }\n        });\n        resolveSceneLabelOverlaps();\n      }\n\n      function getPaddedRect(rect, pad) {\n        return {\n          left: rect.left - pad,\n          top: rect.top - pad,\n          right: rect.right + pad,\n          bottom: rect.bottom + pad,\n        };\n      }\n\n      function screenRectsOverlap(a, b) {\n        return a.left < b.right && a.right > b.left && a.top < b.bottom && a.bottom > b.top;\n      }\n\n      function resolveSceneLabelOverlaps() {\n        // 地点名优先级高于路网标签；子地点出现时不再被避让逻辑直接隐藏。\n        return;\n        const placedRects = [];\n        const sceneLabels = [];\n\n        nodeElements.forEach(({ el, node }) => {\n          if (el.style.display === 'none') return;\n          const label = el.querySelector('.node-label');\n          if (!label) return;\n\n          if (node.type === 'scene') {\n            sceneLabels.push({ label, node });\n            return;\n          }\n\n          if (label.style.opacity !== '0') {\n            placedRects.push(getPaddedRect(label.getBoundingClientRect(), 8));\n          }\n        });\n\n        sceneLabels.forEach(({ label }) => {\n          if (scale < SCENE_LABEL_VISIBLE_SCALE) {\n            label.style.opacity = '0';\n            return;\n          }\n\n          const rect = getPaddedRect(label.getBoundingClientRect(), 6);\n          const overlaps = placedRects.some(placed => screenRectsOverlap(rect, placed));\n          if (overlaps) {\n            label.style.opacity = '0';\n            return;\n          }\n\n          label.style.opacity = scale < 1.7 ? '0.58' : '0.86';\n          placedRects.push(rect);\n        });\n      }\n\n      // ============ DETAIL MODAL ============\n      function openDetail(node) {\n        const cfg = typeConfig[node.iconType || node.type] || typeConfig.poi;\n        const iconSize = 26;\n        const dc = TYPE_COLORS[node.iconType || node.type] || TYPE_COLORS.poi;\n        const briefText = typeof node.brief === 'string' ? node.brief.trim() : '';\n        const summaryText = typeof node.summary === 'string' ? node.summary.trim() : '';\n\n        // Header: icon + name + type badge\n        detailHeader.innerHTML = `\n    <div class=\"detail-title\">\n      <span style=\"width:46px;height:46px;flex-shrink:0;border-radius:13px;display:grid;place-items:center;background:${dc};box-shadow:0 6px 16px -4px ${dc};color:#fff;\">\n        <svg width=\"${iconSize}\" height=\"${iconSize}\" viewBox=\"0 0 32 32\"><use href=\"#icon-${node.iconType || node.type}\"/></svg>\n      </span>\n      <span>${escHtml(node.name)}</span>\n    </div>\n    <div style=\"margin-top:6px; display:flex; flex-wrap:wrap; gap:8px;\">\n      <span class=\"detail-type-badge\" style=\"background:color-mix(in srgb, ${dc} 12%, #fff); color:${dc}; border-color:color-mix(in srgb, ${dc} 32%, #fff);\">${cfg.label}</span>\n      ${node.tier ? `<span class=\"detail-type-badge\" style=\"background:rgba(90,120,160,0.1); color:#4a5c74; border-color:rgba(120,145,180,0.28);\">${escHtml(node.tier)}</span>` : ''}\n    </div>\n  `;\n\n        // Brief / Summary\n        if (briefText) {\n          detailSummary.textContent = briefText;\n          detailSummary.style.display = '';\n        } else if (summaryText) {\n          detailSummary.textContent = summaryText;\n          detailSummary.style.display = '';\n        } else {\n          detailSummary.style.display = 'none';\n        }\n\n        // Body\n        let bodyHtml = '';\n\n        function formatDetailText(str) {\n          const normalized = String(str)\n            .trim()\n            .replace(/。；/g, '；')\n            .replace(/；\\s*；+/g, '；')\n            .replace(/\\s+；/g, '；')\n            .replace(/；\\s+/g, '；');\n          if (!normalized) return '';\n\n          const parts = normalized\n            .split(/；(?=[^；：\\n]{1,12}：)/)\n            .map(part => part.trim())\n            .filter(Boolean);\n          const looksStructured = parts.length >= 2 && parts.every(part => /^[^；：\\n]{1,12}：/.test(part));\n          if (!looksStructured) return escHtml(normalized);\n\n          return `<div class=\"detail-kv-list\">${parts.map(part => {\n            const idx = part.indexOf('：');\n            const key = part.slice(0, idx).trim();\n            const value = part.slice(idx + 1).trim().replace(/；$/g, '');\n            return `<div class=\"detail-kv-row\">\n          <div class=\"detail-kv-key\">${escHtml(key)}：</div>\n          <div class=\"detail-kv-value\">${escHtml(value)}</div>\n        </div>`;\n          }).join('')}</div>`;\n        }\n\n        if (briefText && summaryText && briefText !== summaryText) {\n          bodyHtml += `<div class=\"detail-section\">\n        <div class=\"detail-section-title\">概述</div>\n        <div class=\"detail-section-content\">${formatDetailText(summaryText)}</div>\n      </div>`;\n        }\n\n        // Physical Consequences grid\n        if (node.physicalConsequences && typeof node.physicalConsequences === 'object') {\n          const pc = node.physicalConsequences;\n          // 过滤空值和无意义占位文本\n          const TRIVIAL_RE = /^(因.*而异|正常|倒置|无$|无水|无水源|N\\/A|未知|待定)/;\n          const entries = Object.entries(pc).filter(([k, v]) => {\n            if (!v) return false;\n            const s = String(v).trim();\n            if (!s) return false;\n            if (TRIVIAL_RE.test(s)) return false;\n            // 非 terrain 字段：过于简短的值（<=4字）没有信息量\n            if (k !== 'terrain' && s.length <= 4) return false;\n            return true;\n          });\n          if (entries.length > 0) {\n            bodyHtml += `<div class=\"detail-section\">\n        <div class=\"detail-section-title\">环境</div>\n        <div class=\"detail-grid\">`;\n            entries.forEach(([key, val]) => {\n              const label = PHYSICAL_LABELS[key] || key;\n              bodyHtml += `<div class=\"detail-grid-item\">\n          <div class=\"grid-label\">${escHtml(label)}</div>\n          <div class=\"grid-value\">${escHtml(String(val))}</div>\n        </div>`;\n            });\n            bodyHtml += `</div></div>`;\n          }\n        }\n\n        // All other fields\n        for (const [key, val] of getOrderedNodeEntries(node)) {\n          if (SKIP_FIELDS.has(key)) continue;\n          if (key === 'tier') continue; // already shown in header\n          if (!FIELD_LABELS[key]) continue; // unknown field, skip\n          if (val === null || val === undefined) continue;\n\n          // Check emptiness\n          if (Array.isArray(val)) {\n            if (val.length === 0) continue;\n            // Render as tags\n            bodyHtml += `<div class=\"detail-section\">\n        <div class=\"detail-section-title\">${escHtml(FIELD_LABELS[key])}</div>\n        <div class=\"detail-tags\">`;\n            val.forEach(item => {\n              bodyHtml += `<span class=\"detail-tag\">${escHtml(String(item))}</span>`;\n            });\n            bodyHtml += `</div></div>`;\n          } else if (typeof val === 'object') {\n            // Skip objects (physicalConsequences already handled)\n            continue;\n          } else {\n            const strVal = String(val).trim();\n            if (!strVal) continue;\n            bodyHtml += `<div class=\"detail-section\">\n        <div class=\"detail-section-title\">${escHtml(FIELD_LABELS[key])}</div>\n        <div class=\"detail-section-content\">${formatDetailText(strVal)}</div>\n      </div>`;\n          }\n        }\n\n        // Connected locations\n        const connections = [];\n        edges.forEach(e => {\n          if (e.source === node.id && nodeMap[e.target]) {\n            connections.push({ node: nodeMap[e.target], label: e.label, distance: e.distance });\n          } else if (e.target === node.id && nodeMap[e.source]) {\n            connections.push({ node: nodeMap[e.source], label: e.label, distance: e.distance });\n          }\n        });\n        if (connections.length > 0) {\n          bodyHtml += `<div class=\"detail-connections\">\n      <div class=\"detail-section-title\">连接地点</div>\n      <div style=\"display:flex; flex-wrap:wrap;\">`;\n          connections.forEach(c => {\n            const cCfg = typeConfig[c.node.type] || typeConfig.poi;\n            bodyHtml += `<div class=\"detail-conn-item\" data-target-id=\"${c.node.id}\">\n        <svg width=\"16\" height=\"16\" viewBox=\"0 0 32 32\" style=\"flex-shrink:0;\"><use href=\"#icon-${c.node.iconType || c.node.type}\"/></svg>\n        <span>${escHtml(c.node.name)}</span>\n        ${c.label ? `<span class=\"detail-conn-dist\">· ${escHtml(c.label)}</span>` : ''}\n        ${c.distance ? `<span class=\"detail-conn-dist\">(${escHtml(String(c.distance))})</span>` : ''}\n      </div>`;\n          });\n          bodyHtml += `</div></div>`;\n        }\n\n        detailBody.innerHTML = bodyHtml;\n\n        // Make connection items clickable\n        detailBody.querySelectorAll('.detail-conn-item').forEach(el => {\n          el.addEventListener('click', () => {\n            const targetId = el.dataset.targetId;\n            const targetNode = nodeMap[targetId];\n            if (targetNode) openDetail(targetNode);\n          });\n        });\n\n        // Show modal\n        detailOverlay.classList.add('active');\n        solarisDetailActions(node);\n        detailPanel.scrollTop = 0;\n      }\n\n      function escHtml(str) {\n        const div = document.createElement('div');\n        div.textContent = str;\n        return div.innerHTML;\n      }\n\n      // Close detail modal\n      detailClose.addEventListener('click', () => {\n        detailOverlay.classList.remove('active');\n      });\n      detailOverlay.addEventListener('click', (e) => {\n        if (e.target === detailOverlay) detailOverlay.classList.remove('active');\n      });\n      document.addEventListener('keydown', (e) => {\n        if (e.key === 'Escape') detailOverlay.classList.remove('active');\n      });\n\n      // ============ MINIMAP ============\n      function renderMinimap() {\n        const dpr = devicePixelRatio;\n        const mw = 168 * dpr, mh = 128 * dpr;\n        minimapCtx.clearRect(0, 0, mw, mh);\n\n        let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;\n        nodes.forEach(n => {\n          if (n.type === 'scene') return;\n          const wx = n.x * SPREAD, wy = n.y * SPREAD;\n          if (wx < minX) minX = wx; if (wx > maxX) maxX = wx;\n          if (wy < minY) minY = wy; if (wy > maxY) maxY = wy;\n        });\n        const pad = 100;\n        minX -= pad; maxX += pad; minY -= pad; maxY += pad;\n        const rangeX = maxX - minX, rangeY = maxY - minY;\n        const mScale = Math.min(mw / rangeX, mh / rangeY) * 0.9;\n        const offX = (mw - rangeX * mScale) / 2;\n        const offY = (mh - rangeY * mScale) / 2;\n\n        function miniPos(wx, wy) {\n          return { x: offX + (wx - minX) * mScale, y: offY + (wy - minY) * mScale };\n        }\n\n        // Edges\n        minimapCtx.strokeStyle = 'rgba(120,140,170,0.35)';\n        minimapCtx.lineWidth = 0.6 * dpr;\n        minimapCtx.setLineDash([]);\n        edges.forEach(e => {\n          if (e.type === 'scene') return;\n          const src = nodeMap[e.source], tgt = nodeMap[e.target];\n          if (!src || !tgt) return;\n          if (scale < SCENE_VISIBLE_SCALE && (src.type === 'scene' || tgt.type === 'scene')) return;\n          const s = miniPos(src.x * SPREAD, src.y * SPREAD);\n          const t = miniPos(tgt.x * SPREAD, tgt.y * SPREAD);\n          minimapCtx.beginPath();\n          minimapCtx.moveTo(s.x, s.y);\n          minimapCtx.lineTo(t.x, t.y);\n          minimapCtx.stroke();\n        });\n\n        // Nodes\n        nodes.forEach(n => {\n          if (n.type === 'scene') return;\n          const p = miniPos(n.x * SPREAD, n.y * SPREAD);\n          if (n.id === 'otherspace_thriller_paradise') {\n            minimapCtx.fillStyle = '#dd7a2b';\n            minimapCtx.beginPath();\n            minimapCtx.arc(p.x, p.y, 3.5 * dpr, 0, Math.PI * 2);\n            minimapCtx.fill();\n          } else if (n.independent) {\n            minimapCtx.fillStyle = '#b23fce';\n            minimapCtx.beginPath();\n            minimapCtx.arc(p.x, p.y, 3.5 * dpr, 0, Math.PI * 2);\n            minimapCtx.fill();\n          } else {\n            minimapCtx.fillStyle = TYPE_COLORS[n.iconType || n.type] || '#6b7d94';\n            minimapCtx.beginPath();\n            minimapCtx.arc(p.x, p.y, (['city', 'campus', 'stronghold'].includes(n.type) ? 2.8 : 1.7) * dpr, 0, Math.PI * 2);\n            minimapCtx.fill();\n          }\n        });\n\n        // Viewport rect\n        const cx = window.innerWidth / 2, cy = window.innerHeight / 2;\n        const vpLeft = (-viewX - cx / scale), vpTop = (-viewY - cy / scale);\n        const vpRight = (-viewX + cx / scale), vpBottom = (-viewY + cy / scale);\n        const tl = miniPos(vpLeft, vpTop);\n        const br = miniPos(vpRight, vpBottom);\n        minimapCtx.strokeStyle = 'rgba(47,127,214,0.85)';\n        minimapCtx.lineWidth = 1.4 * dpr;\n        minimapCtx.setLineDash([]);\n        minimapCtx.strokeRect(tl.x, tl.y, br.x - tl.x, br.y - tl.y);\n      }\n\n      // ============ LEGEND ============\n      function buildLegend() {\n        const legendItems = document.getElementById('legend-items');\n        const usedTypes = new Set(nodes.map(n => n.iconType || n.type));\n        Object.keys(typeConfig).forEach(type => {\n          if (!usedTypes.has(type)) return;\n          const cfg = typeConfig[type];\n          const item = document.createElement('div');\n          item.style.cssText = 'display:flex; align-items:center; gap:7px; padding:1px 0;';\n          item.innerHTML = `\n      <svg width=\"18\" height=\"18\" viewBox=\"0 0 32 32\" style=\"flex-shrink:0; color:${TYPE_COLORS[type] || '#6b7d94'};\"><use href=\"#icon-${type}\"/></svg>\n      <span style=\"font-size:12px; color:#3c4c62; white-space:nowrap;\">${cfg.label}</span>\n    `;\n          legendItems.appendChild(item);\n        });\n\n        // Special marker legends\n        const specialSep = document.createElement('div');\n        specialSep.style.cssText = 'grid-column:1/-1; border-top:1px solid rgba(120,145,180,0.2); margin:6px 0 2px; padding-top:6px; font-size:11px; color:#4a5c74; font-weight:700; letter-spacing:0.5px;';\n        specialSep.textContent = '特殊标记';\n        \n\n        const independentLegend = document.createElement('div');\n        independentLegend.style.cssText = 'display:flex; align-items:center; gap:7px; padding:1px 0;';\n        independentLegend.innerHTML = `\n    <span style=\"display:inline-block;width:14px;height:14px;border-radius:50%;border:2px dashed rgba(178,63,206,0.7);flex-shrink:0;\"></span>\n    <span style=\"font-size:12px; color:#9a2fbf; white-space:nowrap;\">独立异空间</span>\n  `;\n        \n\n        const thrillerLegend = document.createElement('div');\n        thrillerLegend.style.cssText = 'display:flex; align-items:center; gap:7px; padding:1px 0;';\n        thrillerLegend.innerHTML = `\n    <span style=\"display:inline-block;width:14px;height:14px;border-radius:50%;border:2px solid rgba(221,122,43,0.75);flex-shrink:0;\"></span>\n    <span style=\"font-size:12px; color:#c0632a; white-space:nowrap;\">中国沿海异常点</span>\n  `;\n        \n\n        // 玩家位置图例\n        const playerLegend = document.createElement('div');\n        playerLegend.style.cssText = 'display:flex; align-items:center; gap:7px; padding:1px 0;';\n        playerLegend.innerHTML = `\n    <span style=\"display:inline-block;width:14px;height:14px;border-radius:50%;border:2px solid rgba(20,170,110,0.75);flex-shrink:0;\"></span>\n    <span style=\"font-size:12px; color:#12a06e; white-space:nowrap;\">当前位置</span>\n  `;\n        legendItems.appendChild(playerLegend);\n      }\n\n      // ============ MAIN RENDER ============\n      function render() {\n        renderEdges();\n        updateNodePositions();\n        renderMinimap();\n        if (editMode && deleteEdgeMode) updateEdgeHitAreas();\n      }\n\n      // ============ PAN ============\n      container.addEventListener('mousedown', (e) => {\n        if (e.target.closest('.node-wrapper')) return;\n        isDragging = true;\n        dragStartX = e.clientX;\n        dragStartY = e.clientY;\n        dragViewX = viewX;\n        dragViewY = viewY;\n        container.classList.add('grabbing');\n      });\n      window.addEventListener('mousemove', (e) => {\n        // Node dragging in edit mode\n        if (nodeDragging) {\n          const dx = (e.clientX - nodeDragStartX) / scale / SPREAD;\n          const dy = (e.clientY - nodeDragStartY) / scale / SPREAD;\n          nodeDragging.x = nodeOrigX + dx;\n          nodeDragging.y = nodeOrigY + dy;\n          render();\n          return;\n        }\n        if (!isDragging) return;\n        viewX = dragViewX + (e.clientX - dragStartX) / scale;\n        viewY = dragViewY + (e.clientY - dragStartY) / scale;\n        render();\n      });\n      window.addEventListener('mouseup', () => {\n        if (nodeDragging) { nodeDragging = null; return; }\n        isDragging = false;\n        container.classList.remove('grabbing');\n      });\n\n      // ============ ZOOM ============\n      container.addEventListener('wheel', (e) => {\n        e.preventDefault();\n        const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;\n        const cx = window.innerWidth / 2;\n        const cy = window.innerHeight / 2;\n        const wx = (e.clientX - cx) / scale - viewX;\n        const wy = (e.clientY - cy) / scale - viewY;\n        scale *= zoomFactor;\n        scale = Math.max(0.15, Math.min(3, scale));\n        viewX = (e.clientX - cx) / scale - wx;\n        viewY = (e.clientY - cy) / scale - wy;\n        render();\n      }, { passive: false });\n\n      function zoomIn() { scale = Math.min(3, scale * 1.2); render(); }\n      function zoomOut() { scale = Math.max(0.15, scale / 1.2); render(); }\n      function resetView() {\n        if (lastMatchedNodeId && nodeMap[lastMatchedNodeId]) {\n          const n = nodeMap[lastMatchedNodeId];\n          viewX = -n.x * SPREAD;\n          viewY = -n.y * SPREAD;\n        } else {\n          viewX = 0; viewY = 0;\n        }\n        scale = 0.65; render();\n      }\n      window.zoomIn = zoomIn; window.zoomOut = zoomOut; window.resetView = resetView;\n\n      // ============ TOUCH SUPPORT ============\n      let lastTouchDist = 0;\n      let lastTouchCenter = null;\n      container.addEventListener('touchstart', (e) => {\n        if (e.touches.length === 1) {\n          isDragging = true;\n          dragStartX = e.touches[0].clientX;\n          dragStartY = e.touches[0].clientY;\n          dragViewX = viewX;\n          dragViewY = viewY;\n        } else if (e.touches.length === 2) {\n          isDragging = false;\n          const dx = e.touches[0].clientX - e.touches[1].clientX;\n          const dy = e.touches[0].clientY - e.touches[1].clientY;\n          lastTouchDist = Math.sqrt(dx * dx + dy * dy);\n          lastTouchCenter = {\n            x: (e.touches[0].clientX + e.touches[1].clientX) / 2,\n            y: (e.touches[0].clientY + e.touches[1].clientY) / 2\n          };\n        }\n      }, { passive: true });\n      container.addEventListener('touchmove', (e) => {\n        e.preventDefault();\n        if (e.touches.length === 1 && isDragging) {\n          viewX = dragViewX + (e.touches[0].clientX - dragStartX) / scale;\n          viewY = dragViewY + (e.touches[0].clientY - dragStartY) / scale;\n          render();\n        } else if (e.touches.length === 2) {\n          const dx = e.touches[0].clientX - e.touches[1].clientX;\n          const dy = e.touches[0].clientY - e.touches[1].clientY;\n          const dist = Math.sqrt(dx * dx + dy * dy);\n          if (lastTouchDist > 0) {\n            const zoomFactor = dist / lastTouchDist;\n            const cx = window.innerWidth / 2;\n            const cy = window.innerHeight / 2;\n            const tcx = (e.touches[0].clientX + e.touches[1].clientX) / 2;\n            const tcy = (e.touches[0].clientY + e.touches[1].clientY) / 2;\n            const wx = (tcx - cx) / scale - viewX;\n            const wy = (tcy - cy) / scale - viewY;\n            scale *= zoomFactor;\n            scale = Math.max(0.15, Math.min(3, scale));\n            viewX = (tcx - cx) / scale - wx;\n            viewY = (tcy - cy) / scale - wy;\n            render();\n          }\n          lastTouchDist = dist;\n        }\n      }, { passive: false });\n      container.addEventListener('touchend', () => {\n        isDragging = false;\n        lastTouchDist = 0;\n        lastTouchCenter = null;\n      });\n\n      // ============ EDIT MODE ============\n      function updateEdgePickHighlight() {\n        nodeElements.forEach(({ el, node }) => {\n          el.classList.toggle('edge-source', addEdgeMode && edgeAddSourceId === node.id);\n        });\n      }\n\n      function updateEditHint() {\n        const hint = document.getElementById('edit-hint');\n        if (!hint) return;\n        if (!editMode) {\n          hint.textContent = '';\n          return;\n        }\n        if (addEdgeMode) {\n          if (edgeAddSourceId && nodeMap[edgeAddSourceId]) {\n            hint.textContent = `已选起点：${nodeMap[edgeAddSourceId].name}，点击目标节点创建连线`;\n          } else {\n            hint.textContent = '点击一个节点作为起点，再点击另一个节点作为终点';\n          }\n          return;\n        }\n        if (deleteEdgeMode) {\n          hint.textContent = '点击连线中间的 × 删除';\n          return;\n        }\n        hint.textContent = '拖拽节点调整位置';\n      }\n\n      function edgeExists(a, b) {\n        return edges.some(e => (\n          (e.source === a && e.target === b) ||\n          (e.source === b && e.target === a)\n        ));\n      }\n\n      function handleEdgeAddNodeClick(node) {\n        if (!editMode || !addEdgeMode) return;\n        const hint = document.getElementById('edit-hint');\n\n        if (!edgeAddSourceId) {\n          edgeAddSourceId = node.id;\n          updateEdgePickHighlight();\n          updateEditHint();\n          return;\n        }\n\n        if (edgeAddSourceId === node.id) {\n          edgeAddSourceId = null;\n          updateEdgePickHighlight();\n          updateEditHint();\n          return;\n        }\n\n        const sourceId = edgeAddSourceId;\n        const targetId = node.id;\n        const srcName = nodeMap[sourceId]?.name || sourceId;\n        const tgtName = nodeMap[targetId]?.name || targetId;\n\n        if (edgeExists(sourceId, targetId)) {\n          edgeAddSourceId = targetId;\n          updateEdgePickHighlight();\n          hint.textContent = `连线已存在：${srcName} ↔ ${tgtName}，已切换起点`;\n          setTimeout(() => {\n            if (editMode && addEdgeMode) updateEditHint();\n          }, 1500);\n          return;\n        }\n\n        let label = window.prompt('请输入连线标签（可留空）', '');\n        if (label === null) label = '';\n        label = label.trim();\n\n        edges.push({ source: sourceId, target: targetId, label });\n        edgeAddSourceId = targetId;\n        updateEdgePickHighlight();\n        render();\n\n        hint.textContent = `已添加连线：${srcName} → ${tgtName}`;\n        setTimeout(() => {\n          if (editMode && addEdgeMode) updateEditHint();\n        }, 1500);\n      }\n\n      function toggleEditMode() {\n        editMode = !editMode;\n        deleteEdgeMode = false;\n        addEdgeMode = false;\n        edgeAddSourceId = null;\n        const btn = document.getElementById('btn-edit-mode');\n        const btnAdd = document.getElementById('btn-add-edge');\n        const btnDel = document.getElementById('btn-delete-edge');\n        const btnExp = document.getElementById('btn-export');\n        btn.classList.toggle('active', editMode);\n        btnAdd.style.display = editMode ? '' : 'none';\n        btnDel.style.display = editMode ? '' : 'none';\n        btnExp.style.display = editMode ? '' : 'none';\n        btnAdd.classList.remove('active');\n        btnDel.classList.remove('active');\n        updateEditHint();\n        // Toggle node cursor\n        nodeElements.forEach(({ el }) => {\n          el.classList.toggle('editing', editMode);\n        });\n        updateEdgePickHighlight();\n        updateEdgeHitAreas();\n      }\n\n      function toggleAddEdge() {\n        if (!editMode) return;\n        addEdgeMode = !addEdgeMode;\n        const btnAdd = document.getElementById('btn-add-edge');\n        const btnDel = document.getElementById('btn-delete-edge');\n\n        if (addEdgeMode) {\n          deleteEdgeMode = false;\n          edgeAddSourceId = null;\n          btnDel.classList.remove('active');\n        } else {\n          edgeAddSourceId = null;\n        }\n\n        btnAdd.classList.toggle('active', addEdgeMode);\n        updateEdgePickHighlight();\n        updateEditHint();\n        updateEdgeHitAreas();\n      }\n\n      function toggleDeleteEdge() {\n        if (!editMode) return;\n        deleteEdgeMode = !deleteEdgeMode;\n        const btnAdd = document.getElementById('btn-add-edge');\n        const btn = document.getElementById('btn-delete-edge');\n\n        if (deleteEdgeMode) {\n          addEdgeMode = false;\n          edgeAddSourceId = null;\n          btnAdd.classList.remove('active');\n        }\n\n        btn.classList.toggle('active', deleteEdgeMode);\n        updateEdgePickHighlight();\n        updateEditHint();\n        updateEdgeHitAreas();\n      }\n\n      // Edge delete hit areas\n      let edgeHitLayer = null;\n      function updateEdgeHitAreas() {\n        if (!edgeHitLayer) {\n          edgeHitLayer = document.createElement('div');\n          edgeHitLayer.id = 'edge-hit-layer';\n          edgeHitLayer.style.cssText = 'position:absolute;top:0;left:0;width:100%;height:100%;pointer-events:none;z-index:3;';\n          container.appendChild(edgeHitLayer);\n        }\n        edgeHitLayer.innerHTML = '';\n        if (!editMode || !deleteEdgeMode) return;\n\n        edges.forEach((e, idx) => {\n          const src = nodeMap[e.source];\n          const tgt = nodeMap[e.target];\n          if (!src || !tgt) return;\n          if (scale < SCENE_VISIBLE_SCALE && (src.type === 'scene' || tgt.type === 'scene')) return;\n          const path = buildEdgePath(e, src, tgt);\n          const mid = edgePathPoint(path, 0.5);\n          const mx = mid.x;\n          const my = mid.y;\n\n          const btn = document.createElement('div');\n          btn.className = 'edge-delete-hit';\n          btn.style.cssText = `\n      left:${mx - 12}px; top:${my - 12}px; width:24px; height:24px;\n      background:rgba(180,50,50,0.8); border-radius:50%; pointer-events:auto;\n      display:flex; align-items:center; justify-content:center;\n      font-size:14px; color:#fff; cursor:pointer; border:1px solid rgba(255,100,100,0.5);\n    `;\n          btn.textContent = '×';\n          btn.title = `删除: ${e.label || e.source + ' → ' + e.target}`;\n          btn.addEventListener('click', (ev) => {\n            ev.stopPropagation();\n            deletedEdges.push(edges.splice(idx, 1)[0]);\n            render();\n            updateEdgeHitAreas();\n          });\n          edgeHitLayer.appendChild(btn);\n        });\n      }\n\n      // Re-render hit areas on pan/zoom is handled in render()\n\n      function exportData() {\n        // Build updated JSON\n        const exportObj = JSON.parse(JSON.stringify(MAP_DATA.mapData ? MAP_DATA : { mapData: MAP_DATA.mapData }));\n        // Update node positions\n        const expMapData = exportObj.mapData || exportObj;\n        expMapData.nodes = nodes.map(n => {\n          const copy = {};\n          for (const [k, v] of getOrderedNodeEntries(n)) {\n            copy[k] = v;\n          }\n          // Round coordinates\n          copy.x = Math.round(n.x * 100) / 100;\n          copy.y = Math.round(n.y * 100) / 100;\n          return copy;\n        });\n        expMapData.edges = edges.map(e => ({ ...e }));\n\n        const jsonStr = JSON.stringify(exportObj, null, 2);\n        const blob = new Blob([jsonStr], { type: 'application/json' });\n        const url = URL.createObjectURL(blob);\n  