            }
            applyAmberMapFrameToDom();
            applyDungeonMapFrameToDom();
            // 向地图 iframe 推送位置数据
            try {
              const 世界信息 = data.世界信息 || {};
              const 位置 = 世界信息.位置 || {};
              const mapMsg = { type: 'mvu_location', 位置, 时间: 世界信息.时间 || '', 年历: 世界信息.年历 || '' };
              document.querySelectorAll('iframe').forEach(f => {
                try { f.contentWindow.postMessage(mapMsg, '*');
                  if(f.dataset.worldviewMode==='earthsea' && data?.系统配置?.世界观==='诡秘地海') {
                    f.contentWindow.postMessage({type:'earthsea_state',stat_data:data},new URL(f.src).origin);
